INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Agglutination Assay', 'An agglutination assay detects and quantifies antibody-antigen interaction through visible clumping of particles. Serial dilutions of antiserum are mixed with target particles, which may be bacteria, antigen-coated red blood cells or conjugated latex beads, and after incubation the wells are read visually or by turbidimetry, with agglutinated samples showing dispersed mats or granular clumps while negative samples form tight pellets. Results are reported as the agglutination titer, the highest dilution that still produces visible clumping, together with a strength score for each well.', 'agglutination, hemagglutination, latex agglutination, antigen-antibody clumping, particle agglutination, serological titer, turbidimetric assay, immunoassay, agglutination titer, hemagglutination inhibition, HAI assay, microagglutination, slide agglutination, tube agglutination', NULL, 'CHM', NULL, 'D.IMG or CHM', 'Source', 'Raw', NULL, NULL, NULL, NULL, NULL, 1);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Analyzed Spatial Proteomics', 'Spatial proteomics is a methodology that maps the distribution, abundance, and localization of proteins within tissue sections or cellular compartments while preserving spatial context. This assay typically employs imaging-based platforms such as multiplex immunofluorescence, imaging mass cytometry (IMC), or Digital Spatial Profiling (DSP) to simultaneously detect and quantify multiple protein targets at defined spatial coordinates. Sample preparation generally involves formalin-fixed paraffin-embedded (FFPE) or fresh-frozen tissue sections subjected to antigen retrieval, antibody staining or metal-conjugated probe hybridization, followed by high-resolution image acquisition and computational analysis to deconvolve protein expression patterns across tissue microenvironments. The resulting spatially resolved proteomic data enables characterization of cell phenotypes, cell-cell interactions, and tissue architecture in the context of disease states or biological processes.', 'spatial proteomics analysis, Digital Spatial Profiling, DSP analysis, multiplex immunofluorescence analysis, IMC analysis, imaging mass cytometry analysis, spatial protein mapping, image analysis, GeoMx analysis, CODEX analysis, PhenoCycler analysis, spatial cell phenotyping, spatial neighborhood analysis, spatial omics analysis', NULL, 'D.IMG', NULL, 'A.IMG', 'Raw', 'Analyzed', NULL, NULL, NULL, NULL, NULL, 2);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Antibody Functional Profiling (Systems Serology)', 'This is the analysis step for antibody-dependent functional profiling, also recorded as ADFP. Raw readouts from the individual effector assays, covering Fc receptor binding, cellular and neutrophil phagocytosis, complement deposition and NK cell activation, are background corrected, scored and normalized so results can be compared across plates, antigens and subjects. The per-feature scores are then combined into multivariate profiles describing the polyfunctional antibody response to infection, vaccination or treatment.', 'systems serology, Fc functional profiling, ADCP ADNP ADCD ADNKA, humoral immune profiling, antibody effector multiplex, Alter lab systems serology, antibody profiling analysis, systems serology analysis, Fc function analysis, immune effector function analysis, antibody Fc profiling, functional antibody profiling, antibody effector function profiling, polyfunctional antibody response, antibody-dependent functional profiling analysis, ADFP, Fc effector function analysis, humoral immune profiling analysis, multiplexed functional readout, ADFP analysis, Fc effector score, antibody polyfunctionality analysis, effector function profile analysis', 'Antibody Functional Profiling Analysis, ADFP Analysis', 'D.FCRB or D.ADCP or D.ADCD or D.ADNKA or D.ADNP or D.ADDCP or D.ADMP', NULL, 'A.FCRB or A.ADCP or A.ADCD or A.ADNKA or A.ADNP or A.ADDCP or A.ADMP or A.FPCL', 'Raw', 'Analyzed', NULL, NULL, NULL, NULL, NULL, 119);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Antibody Titer Assay Analysis', 'This step derives titer values from raw titer assay readings. Dilution series responses are fitted to dose-response curves to obtain endpoint titers, half-maximal values or area under the curve, with the same fitting and cutoff rules applied to every sample so results stay comparable. Outputs are per-sample titer tables in consistent units, together with curve fit diagnostics.', 'antibody titer assay analysis, bead-based titer analysis, multiplex titer analysis, serology data analysis, titer analysis, serology analysis, antibody level analysis, endpoint titer analysis, neutralization titer analysis, systems serology analysis, titer curve fitting, EC50 titer, dilution curve analysis', 'Titer Assay Analysis, Antibody Titer Analysis', 'D.TITR', NULL, 'A.TITR', 'Raw', 'Analyzed', NULL, NULL, NULL, NULL, NULL, 104);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Antibody-Dependent Cellular Phagocytosis (ADCP)', 'Antibody-dependent cellular phagocytosis (ADCP) is a functional humoral immune assay that quantifies the capacity of antigen-specific antibodies to facilitate phagocytic uptake of antibody-opsonized targets by effector cells, typically monocytes or neutrophils. The assay generally employs fluorescently labeled antigen-coupled beads or target cells incubated with heat-inactivated serum or plasma samples, followed by co-culture with phagocytic effector cells, with uptake measured by flow cytometry. A phagocytosis score is calculated based on the percentage of phagocyte-positive cells and the fluorescence intensity of internalized signal, providing a quantitative readout of Fc-mediated effector function. This assay is commonly used in vaccine immunogenicity studies and therapeutic antibody evaluations to assess non-neutralizing antibody effector functions that may contribute to protective immunity.', 'ADCP, phagocytosis assay, opsonophagocytosis, THP-1 phagocytosis, monocyte phagocytosis, bead uptake, antibody-mediated phagocytosis, bead uptake assay, systems serology, ADCP assay, Fc-mediated phagocytosis, opsonophagocytic assay, antibody-dependent phagocytosis', 'Antibody-Dependent Cellular Phagocytosis', 'TIS and AB', NULL, 'D.ADCP', 'Processed', 'Raw', NULL, NULL, NULL, NULL, NULL, 151);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Antibody-Dependent Cellular Phagocytosis Analysis', 'Antibody-dependent cellular phagocytosis analysis processes raw uptake data to quantify immune cell activity. It calculates phagocytic scores, normalizes results, and generates comparative summaries.\nInput: Raw phagocytosis data\nOutput: Processed activity metrics and visualized response profiles.', 'ADCP analysis, phagocytosis data analysis, opsonophagocytosis analysis, phagocytic score analysis, systems serology analysis, phagocytic score, phagoscore, bead uptake analysis, THP-1 phagocytosis analysis, phagocytosis quantification, Fc-mediated phagocytosis analysis', NULL, 'D.ADCP', NULL, 'A.ADCP', 'Raw', 'Analyzed', NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Antibody-Dependent Complement Deposition (ADCD) Assay', 'Antibody-dependent complement deposition (ADCD) is a functional humoral immune assay that quantifies the ability of antigen-specific antibodies to activate the complement cascade and deposit complement components (typically C3) onto antigen-coated beads or target surfaces. In this assay, immune complexes formed between sample antibodies and antigen are incubated with a complement source, and subsequent complement deposition is measured by flow cytometry using fluorescently labeled anti-C3 detection reagents. Sample preparation involves heat inactivation of endogenous complement in test sera, followed by incubation with antigen-coupled beads and guinea pig or human complement. Data are acquired on a flow cytometer and reported as median fluorescence intensity (MFI), reflecting the magnitude of complement fixation activity in the sample.', 'ADCD assay, complement deposition assay, C3 deposition, complement fixation, opsonization complement assay, ADCD, complement activation, opsonization complement, antibody complement fixing, complement deposition, C3 deposition assay, opsonization, systems serology, C3b deposition, classical complement pathway', 'ADCD Analysis, Antibody Dependent Complement Deposition, Antibody-dependent Complement Deposition', 'TIS and AB', NULL, 'D.ADCD', 'Processed', 'Raw', NULL, NULL, NULL, NULL, NULL, 149);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Antibody-Dependent Functional Profiling (ADFP)', 'Antibody Dependent Functional Profiling (ADFP) is a multiplexed assay that characterizes the functional capacity of antigen-specific antibodies by simultaneously measuring multiple Fc-mediated effector functions, including antibody-dependent cellular cytotoxicity (ADCC), antibody-dependent cellular phagocytosis (ADCP), antibody-dependent neutrophil phagocytosis (ADNP), and complement deposition (ADCD). The assay employs Luminex-based bead arrays coupled with flow cytometry to profile antibody-mediated recruitment and activation of innate immune effector cells, utilizing fluorescently labeled antigen-coupled microspheres incubated with serum samples and relevant effector cells or complement sources. Data outputs include median fluorescence intensity (MFI) and phagocytic or cytotoxic scores derived from multiparameter flow cytometric analysis, enabling high-throughput, systems-level characterization of humoral immune responses across large sample cohorts.', 'ADFP, antibody-dependent functional profiling, systems serology, Fc effector function, immune functional fingerprint, antibody effector function, functional immune profiling, Fc effector profiling, humoral immune function, ADFP assay, Fc effector function panel, multiplexed antibody effector assay', 'Antibody Dependent Functional Profiling, Antibody Functional Profiling', 'TIS and AB', 'CEL', 'D.ADCD or D.ADCP or D.ADNKA or D.ADNP or D.ADMP or D.ADDCP', 'Processed', 'Raw', NULL, NULL, NULL, NULL, NULL, 153);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Antibody-Dependent Neutrophil Phagocytosis (ADNP)', 'Antibody-Dependent Neutrophil Phagocytosis (ADNP) is a functional immunoassay that measures the capacity of antigen-specific antibodies to opsonize targets and drive their uptake by primary human neutrophils via Fc receptor engagement. Antigen-coated fluorescent beads or immune complexes are incubated with serum or plasma, then combined with freshly isolated neutrophils. After incubation, phagocytic activity is quantified by flow cytometry, measuring the percentage of neutrophils that have internalized fluorescent beads and/or the fluorescence intensity per cell. Results are reported as a phagocytic score (percent positive cells × mean fluorescence intensity) providing a functional measure of antibody-dependent neutrophil phagocytosis (ADNP) activity mediated by innate immune effector cells. ADNP is a key component of systems serology profiling, reflecting the ability of antibodies to recruit neutrophil-mediated clearance mechanisms.', 'ADNP, neutrophil phagocytosis assay, granulocyte phagocytosis, antibody-mediated neutrophil uptake, neutrophil phagocytosis, innate immune effector, systems serology, ADNP assay, Fc-mediated neutrophil phagocytosis, primary neutrophil phagocytosis, HL-60 phagocytosis, neutrophil bead uptake', 'Antibody-dependent Neutrophil Phagocytosis', 'TIS and AB', NULL, 'D.ADNP', 'Processed', 'Raw', NULL, NULL, NULL, NULL, NULL, 150);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Antibody-Dependent Neutrophil Phagocytosis Analysis', 'Antibody-dependent neutrophil phagocytosis analysis processes raw neutrophil uptake data to quantify immune performance. It aggregates fluorescence or imaging results across replicates to identify response patterns.\nInput: Raw neutrophil phagocytosis data\nOutput: Normalized uptake metrics and comparative summaries.', 'ADNP analysis, neutrophil phagocytosis analysis, granulocyte assay analysis, innate effector analysis, systems serology analysis, neutrophil phagocytic score, neutrophil bead uptake analysis, neutrophil phagocytosis quantification, HL-60 phagocytosis analysis, Fc-mediated neutrophil phagocytosis analysis', NULL, 'D.ADNP', NULL, 'A.ADNP', 'Raw', 'Analyzed', NULL, NULL, NULL, NULL, NULL, 154);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Antibody-Dependent NK Cell Activation Analysis', 'Antibody-dependent NK cell activation analysis processes activation readouts to quantify NK cell responses. It compiles signal intensities or cytokine levels to compare antibody-mediated activation across conditions.\nInput: Raw NK cell activation data\nOutput: Processed activation summaries and response metrics.', 'ADNKA analysis, NK cell activation analysis, ADCC analysis, cytokine secretion analysis, NK degranulation analysis, systems serology analysis, CD107a degranulation analysis, NK cell IFN-gamma analysis, MIP-1beta analysis, NK activation quantification', NULL, 'D.ADNKA', NULL, 'A.ADNKA', 'Raw', 'Analyzed', NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Antibody-Dependent NK Cell Activation Assay', 'This assay measures antibody-dependent NK cell activation by quantifying the functional response of natural killer (NK) cells stimulated in the presence of specific antibodies bound to target antigens. The assay evaluates NK cell activation markers (such as CD107a degranulation and/or intracellular cytokine production, e.g., IFN-γ) using flow cytometry-based detection, reflecting the ability of antibodies to engage NK cell Fc receptors (primarily FcγRIII/CD16) and drive effector responses. Sample preparation typically involves co-culturing peripheral blood mononuclear cells (PBMCs) or purified NK cells with antibody-coated target cells, followed by staining with fluorochrome-conjugated antibodies and acquisition on a multi-parameter flow cytometer. Data are analyzed to determine the frequency or magnitude of activated NK cell populations, providing a functional readout of antibody-mediated innate immune engagement relevant to vaccine and therapeutic antibody research.', 'ADNKA assay, NK cell activation assay, natural killer cell assay, ADCC assay, antibody-dependent cytotoxicity assay, ADNKA, NK cell activation, natural killer cell activation, ADCC, NK cytotoxicity, antibody-dependent cytotoxicity, systems serology, CD107a degranulation, NK degranulation assay, IFN-gamma NK assay', 'Antibody-Dependent NK Cell Activation', 'TIS and AB', NULL, 'D.ADNKA', 'Processed', 'Raw', NULL, NULL, NULL, NULL, NULL, 152);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Area Under the Curve (AUC)', 'Area Under the Curve (AUC) is a mathematical integration method used to summarize the cumulative magnitude of a measured response over time or across a range of conditions. In biological research, AUC is applied to diverse data types: antibody binding curves, dose-response relationships, viral load kinetics, cytokine secretion time courses, and analyte abundance profiles. The calculation integrates the area between the response curve and the baseline (typically via the trapezoidal rule), yielding a single scalar value that captures both the intensity and duration of the measured response. For example, in pharmacokinetics, AUC quantifies total drug exposure over time, while in serology, it summarizes total antibody reactivity across antigen concentrations. AUC values enable standardized comparison across experimental groups, time points, or treatment conditions. Results are reported in units of [response × independent variable] (e.g., OD × concentration, copies/mL × days) and are commonly used as summary endpoints in vaccine immunogenicity, therapeutic efficacy, and biomarker studies.', 'AUC, area under the curve, pharmacokinetics AUC, dose-response AUC, ROC-AUC, bioavailability, exposure calculation, statistics, area under curve, trapezoidal rule, incremental AUC, iAUC, cumulative response, AUC calculation', 'Area Under the Curve', 'D.ELSA', NULL, 'A.ELSA', 'Raw', 'Analyzed', NULL, NULL, NULL, NULL, NULL, 160);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Atomic Force Microscopy (AFM)', 'Atomic force microscopy uses a cantilever probe to map surface topography and mechanical properties at the nanoscale. The sample is mounted on a flat substrate such as glass or mica and scanned in contact, non-contact or tapping mode, and force-distance curves are recorded at defined points to probe stiffness and adhesion. It yields topographic images and force curves from which surface roughness, elastic modulus and adhesion forces are derived.', 'AFM, atomic force microscopy, nanoscale surface imaging, tip-sample interaction, surface stiffness, nanoindentation, topography mapping, nanoscale imaging, surface topography, force spectroscopy, cantilever scanning, microscopy, scanning probe microscopy, Young\'s modulus, force mapping', 'Atomic Force Microscopy', 'SNSR', NULL, 'D.IMG', 'Processed', 'Raw', NULL, NULL, NULL, NULL, NULL, 165);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Bacterial Extraction', 'Bacterial extraction isolates bacteria or bacterial components from mixed cultures or host material. It produces purified material suitable for downstream molecular assays.\nInput: Mixed culture or infected biological material\nOutput: Purified bacterial sample or extract.', 'bacterial isolation, bacteria extraction, microbial extraction, pathogen isolation, bacterial culture isolation, sample preparation, bacterial recovery, bacterial harvest, bacterial isolation from tissue, Mtb isolation, bacterial pellet', NULL, 'TIS or CEL', NULL, 'BAC', 'Processed', 'Source', NULL, NULL, NULL, NULL, NULL, 88);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Bacterial Survivability Restriction Assay', 'This assay measures how far antibodies and host cells restrict bacterial survival, most often Mycobacterium tuberculosis. Bacteria are combined with the antibody sample and with host cells, incubated, and the surviving bacteria are counted by colony forming units, luminescence or fluorescence against untreated controls. It yields restriction and survival readings for each antibody and condition tested.\nInput: Antibody (AB) with bacteria (BAC) and host cells (CEL)\nOutput: Bacterial restriction data (D.BSRA).', 'BSRA, bacterial killing assay, antimicrobial assay, bacterial viability assay, growth inhibition, luminescent bacteria assay, infection restriction, cell-based assay, antibody-mediated bacterial restriction, macrophage infection assay, intracellular bacterial growth, Mtb restriction, CFU counting, colony forming units', NULL, 'AB or BAC or CEL or TIS', NULL, 'D.BSRA', 'Processed', 'Raw', NULL, NULL, NULL, NULL, NULL, 135);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Bulk DNA Sequencing', 'Bulk DNA sequencing is a high-throughput genomic assay that measures DNA sequence information across a population of cells simultaneously, capturing the aggregate genetic landscape of a sample without single-cell resolution. This method typically involves extraction and fragmentation of genomic DNA, library preparation (including adapter ligation and optional target enrichment or amplification), and sequencing on next-generation sequencing (NGS) platforms such as Illumina instruments. The resulting sequence reads are aligned to a reference genome and analyzed bioinformatically to identify genetic variants, structural alterations, copy number changes, or other genomic features present within the bulk cell population.', 'WGS, whole genome sequencing, WES, whole exome sequencing, bulk sequencing, population-level sequencing, NGS DNA sequencing, sequencing, DNA-seq, DNA sequencing, genomic DNA sequencing, exome sequencing, whole-genome sequencing, genome sequencing', NULL, 'DNA', NULL, 'D.SEQ', 'Processed', 'Raw', NULL, 'SRA', NULL, NULL, NULL, 188);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Cancer Cell Extravasation Analysis', 'This step quantifies cancer cell extravasation from imaging of vascularized microfluidic devices. Image series are segmented to identify tumor cells and the vessel wall, and cells are classified by whether they have crossed the endothelium, giving counts, extravasation rates and distances migrated beyond the vessel. Outputs are per-device measurement tables used to compare invasive potential across cell lines, treatments and vascular conditions.', 'extravasation analysis, metastasis assay analysis, transendothelial migration analysis, vascular barrier analysis, invasion analysis, tumor cell motility analysis, organ-on-chip analysis, extravasation assay, tumor cell extravasation, transendothelial migration, extravasation efficiency, microfluidic extravasation', NULL, 'D.IMG', NULL, 'A.CCE or A.CCI', 'Raw', 'Analyzed', NULL, NULL, NULL, NULL, NULL, 79);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('cDNA Synthesis', 'Reverse transcription of isolated RNA into complementary DNA (cDNA) is performed to enable downstream gene expression analyses such as quantitative PCR or RNA sequencing. Total RNA samples are converted to cDNA using reverse transcriptase enzymes, typically in the presence of oligo(dT) or random hexamer primers, dNTPs, and appropriate buffer conditions. The resulting cDNA library serves as a stable, amplifiable template that accurately reflects the RNA transcriptome of the biological sample at the time of collection.', 'reverse transcription, cDNA synthesis, first-strand synthesis, RNA to DNA conversion, RT, complementary DNA preparation, sequencing, cDNA, reverse transcriptase, first-strand cDNA synthesis, SuperScript, oligo(dT) priming, random hexamer priming', 'cDNA Generation', 'RNA', NULL, 'DNA', 'Processed', 'Processed', NULL, NULL, NULL, NULL, NULL, 173);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Cell Culture', 'Cell culture maintains and propagates cells under controlled laboratory conditions. The process provides a stable environment for growth, manipulation, and experimentation.\nInput: Primary cells or established cell line\nOutput: Cultured cells ready for downstream assays.', 'in vitro culture, cell growth, cell propagation, cell maintenance, tissue culture, cell expansion, cell passage, cell culture, primary cell culture, cell line culture, 2D culture, monolayer culture, subculture, bacterial culture', NULL, 'CEL or BAC', NULL, 'CEL', 'Source', 'Source', NULL, NULL, NULL, NULL, NULL, 85);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Cell Culture and Organoid Generation', 'This assay covers the culture of primary cells and cell lines and their use to generate three-dimensional organoid, spheroid and tumoroid models. Cells are propagated under defined media and incubation conditions, then embedded in extracellular matrix scaffolds or seeded in low-attachment formats so they self-organize into three-dimensional structures. Cultures are monitored for growth, viability and morphology, and the resulting cell and organoid material is used in imaging, treatment and molecular assays.', 'organoid culture, 3D cell culture, organoid formation, spheroid culture, mini-organ culture, 3D tissue model, tumoroid, tumor organoid, 3D tumor model, cancer organoid, tumor spheroid, patient-derived organoid, tumor 3D culture, cell culture, organoid', 'Cell Culture and Tumor Spheroid Creation, Tumoroid Formation', 'CEL or TIS', NULL, 'CEL', 'Source', 'Source', NULL, NULL, NULL, NULL, NULL, 96);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Cell Extraction', 'Cell extraction releases the soluble contents of cells so they can be measured. Tissue or cultured cells are disrupted mechanically or enzymatically and the material is clarified, giving a cell extract rather than a suspension of intact cells. The extract feeds protein, immunoassay and mass spectrometry workflows.\nInput: Tissue (TIS) or cells (CEL)\nOutput: Cell extract (CEX).', 'cell isolation, cell dissociation, cell extraction, tissue dissociation, enzymatic dissociation, single cell suspension, sample preparation, tissue digestion, collagenase digestion, mechanical dissociation, tissue disaggregation', NULL, 'CEL or TIS or OOC', NULL, 'CEL or CEX', 'Processed', 'Processed', NULL, NULL, NULL, NULL, NULL, 86);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Cell Imaging', 'Cell imaging records microscopy images of cultured cells, either fixed at a timepoint or followed live over time. Cells are imaged in brightfield, phase contrast or fluorescence on widefield, confocal or time-lapse systems, with staining or reporter expression marking the structures of interest. It yields image sets capturing cell morphology, number, spatial distribution and signal intensity for later quantification.', 'cell microscopy, cellular imaging, fluorescence cell imaging, fixed cell imaging, brightfield imaging, cell visualization, culture imaging, time-lapse cell imaging, live cell culture imaging, phase contrast imaging, live cell imaging, time-lapse microscopy, real-time imaging, in vitro live fluorescence, dynamic cell imaging, microscopy', 'Cell Culture Imaging, Live Cell Imaging', 'CEL', NULL, 'D.IMG', 'Source', 'Raw', NULL, NULL, NULL, NULL, NULL, 164);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Cell Isolation', 'Cell isolation separates and purifies a specific cell population from a biological sample, such as tissue or blood, using methods like enzymatic or mechanical dissociation, density gradient centrifugation, or fluorescence- or magnetic-activated cell sorting. Viability and purity checks confirm the isolated cells are fit for downstream analysis.', 'cell isolation, cell sorting, cell separation, cell purification, immunomagnetic isolation, negative selection, positive selection, sample preparation, MACS, magnetic-activated cell sorting, density gradient centrifugation, Ficoll separation, cell enrichment', NULL, 'CEL or MUS or TIS', NULL, 'CEL or CEX', 'Source', 'Source', NULL, NULL, NULL, NULL, NULL, 87);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Cell Line Creation', 'Cell line creation encompasses the processes used to establish stable or transient cell populations derived from primary tissues, immortalization procedures, or genetic engineering strategies for use in downstream biological assays. This workflow typically involves transfection or transduction of target constructs, selection under appropriate antibiotic or fluorescent marker pressure, single-cell cloning, and expansion of confirmed clones. Resulting cell lines are characterized for expression of relevant transgenes or endogenous targets, genomic integrity, and phenotypic stability prior to use in functional studies. These engineered or adapted cell populations serve as reproducible biological reagents for a broad range of in vitro experimental applications.', 'cell line establishment, cell immortalization, stable line generation, transfection, clonal selection, cell engineering, cell culture, stable cell line, lentiviral transduction, transduction, reporter cell line, single-cell cloning, CRISPR cell line, knockout cell line', NULL, 'MUS or TIS', NULL, 'CEL', 'Source', 'Source', NULL, NULL, NULL, NULL, NULL, 97);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Cell Lysate Preparation', 'This assay involves the preparation of cell lysate samples through a standardized workflow encompassing cell culture maintenance and subsequent chemical or mechanical lysis of harvested cells. Cells are cultured under defined conditions following an established cell culture protocol, then subjected to a treatment and lysis procedure designed to disrupt cellular membranes and release intracellular contents into a soluble fraction. The resulting lysates serve as biological starting material for downstream biochemical or molecular analyses, such as protein quantification, Western blotting, or other cell-based endpoint measurements.', 'cell lysis preparation, lysate preparation, RIPA lysis, protein extraction cells, bead homogenization, freeze-thaw lysis, cell lysis, cellular homogenate, intracellular protein release, mechanical lysis, detergent lysis, sample preparation, whole cell lysate, lysis buffer, sonication', 'Cell Lysate', 'CEL', NULL, 'LYS', 'Source', 'Processed', NULL, NULL, NULL, NULL, NULL, 123);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Cell Sorting', 'Cell sorting physically separates a mixed cell population into defined subpopulations. Cells are stained with fluorescently conjugated antibodies or dyes, interrogated by laser on a sorter and deflected into collection vessels according to a gating strategy, the approach also known as fluorescence-activated cell sorting. It yields purified cell fractions, with sort statistics such as yield and purity, for culture, sequencing and functional assays.', 'FACS, fluorescence-activated cell sorting, cell sorting, flow-based cell separation, electrostatic deflection sorting, cell fractionation, cytometry, flow sorting, cell sorter, sort purity, flow-based separation, live cell sorting, electrostatic cell deflection, FACSAria, fluorescence sorting, flow cytometric sorting, sorted population', 'Fluorescence-Activated Cell Sorting, Fluorescence-Activated Cell Sorting (FACS)', 'TIS', 'D.FLOW', 'CEL', 'Processed', 'Source', NULL, NULL, NULL, NULL, NULL, 13);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Cell Viability Assay', 'Cell viability assays quantify the proportion of live, dead, or metabolically active cells within a population to assess cytotoxicity, proliferation, or treatment response. These assays commonly employ colorimetric, fluorometric, or luminometric methods, such as MTT/MTS reduction, ATP-based luminescence (e.g., CellTiter-Glo), or membrane integrity dyes, to generate a measurable signal proportional to the number of viable cells. Results are typically normalized to untreated controls and expressed as percent viability or relative survival, enabling quantitative comparison across experimental conditions or compound concentrations.', 'cell viability assay, MTS assay, MTT assay, WST-1, CellTiter-Glo, live/dead staining, cytotoxicity measurement, viability assay, cytotoxicity assay, cell survival, cell death assessment, metabolic activity assay, proliferation assay, cell-based assay, AlamarBlue', 'Cell Viability', 'CEL', NULL, 'D.VIA', 'Source', 'Raw', NULL, NULL, NULL, NULL, NULL, 134);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Chemical Challenge', 'This assay exposes a subject or a sample to a defined chemical agent under controlled conditions. Animals, most often mice, are dosed at a set amount, route and schedule and then sampled for downstream analysis, and water samples can likewise be spiked with a defined compound. The challenged animal or the treated water is the source material that later collection and measurement steps draw on.', 'chemical exposure, drug challenge, compound treatment, small molecule challenge, chemical administration, toxicity challenge, in vivo, in vivo exposure, dosing study, toxicology study, animal dosing', NULL, 'CHM', NULL, 'MUS or WTR', 'Source', 'Source', NULL, NULL, NULL, NULL, NULL, 14);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Chemical Synthesis', 'Chemical synthesis combines reagents under controlled conditions to produce specific compounds or molecules. The assay focuses on generating pure and reproducible products for experimental or analytical use.\nInput: Chemical precursors or reagents\nOutput: Synthesized compound or purified chemical sample.', 'organic synthesis, compound synthesis, chemical preparation, drug synthesis, synthetic chemistry, reaction product, reagent preparation, synthesis, small molecule synthesis, polymer synthesis, synthetic route, chemical reaction', NULL, 'CHM', NULL, 'CHM', 'Source', 'Source', NULL, NULL, NULL, NULL, NULL, 117);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Chromatin Sequencing Analysis', 'Chromatin sequencing analysis is a genomic assay that interrogates the structural and regulatory landscape of chromatin by sequencing DNA associated with specific chromatin states, protein binding sites, or accessibility regions. This approach typically employs next-generation sequencing (NGS) technologies following chromatin preparation steps such as immunoprecipitation (ChIP-seq), transposase-based accessibility profiling (ATAC-seq), or nuclease digestion (MNase-seq or FAIRE-seq), depending on the specific application. The resulting sequencing data are computationally processed through alignment, peak calling, and downstream statistical analyses to identify genomic loci associated with transcription factor binding, histone modifications, or open chromatin regions. This assay provides high-resolution, genome-wide maps of chromatin organization that are linked to functional regulatory elements and gene expression data.', 'ATAC-seq analysis, ChIP-seq analysis, chromatin accessibility analysis, epigenomics analysis, histone modification analysis, open chromatin analysis, regulatory element mapping, sequencing analysis, ATAC-seq, ChIP-seq, CUT&RUN, CUT&Tag, peak calling, MACS2, differential accessibility', NULL, 'D.SEQ', NULL, 'A.CHRM', 'Raw', 'Analyzed', NULL, 'GEO', NULL, NULL, NULL, 16);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('CITE-seq (Cellular Indexing of Transcriptomes and Epitopes by Sequencing)', 'CITE-seq measures the transcriptome and the surface protein levels of the same single cells by combining single-cell RNA sequencing with oligonucleotide-tagged antibodies. The step takes the paired sequencing files and produces one integrated single-cell matrix, aligning and counting RNA reads, demultiplexing and normalizing antibody-derived tag counts, and joining the two modalities per cell barcode. The output supports clustering, cell type assignment and joint interpretation of gene and surface protein expression.', 'CITE-seq, multimodal single cell sequencing, antibody-derived tags, ADT sequencing, surface protein RNA co-sequencing, protein RNA multiomics, CITE-seq analysis, multimodal single cell analysis, ADT RNA integration, surface protein expression analysis, multiomics single cell, sequencing, CITEseq, TotalSeq, 10x Feature Barcoding', 'CITESEQ Analysis', 'D.SEQ', NULL, 'A.SCXP', 'Raw', 'Analyzed', NULL, 'GEO', NULL, NULL, NULL, 109);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Clot Modeling Analysis', 'This step analyzes imaging of clot formation to describe how a clot develops and how stable it is. Image series are processed to measure fibrin network structure, clot area and growth over time, and those measurements are fitted to mechanical or kinetic models that yield parameters such as polymerization rate, network density and stiffness. Outputs are per-experiment parameter tables used to compare coagulation across conditions, treatments and donors.', 'clot analysis, coagulation modeling, fibrin network analysis, blood clot mechanics, thrombus analysis, viscoelastic clot analysis, organ-on-chip analysis, clot formation analysis, coagulation analysis, thrombosis analysis, clotting kinetics, fibrin polymerization, hemostasis analysis', NULL, 'D.IMG', NULL, 'A.CLOT', 'Raw', 'Analyzed', NULL, NULL, NULL, NULL, NULL, 83);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Comet Chip Analysis', 'Comet chip analysis quantifies DNA damage from imaging data collected in comet chip assays. It calculates tail length, moment, and intensity metrics to compare sample damage levels.\nInput: Raw comet chip imaging data\nOutput: Processed DNA damage metrics and visual summaries.', 'comet chip analysis, DNA damage quantification, tail length analysis, tail moment analysis, comet image analysis, genotoxicity analysis, DNA damage analysis, comet assay analysis, CometChip analysis, percent tail DNA, olive tail moment', NULL, 'D.IMG', NULL, 'A.COMC', 'Raw', 'Analyzed', NULL, NULL, NULL, NULL, NULL, 185);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('CometChip Assay', 'The CometChip assay measures DNA strand breaks in single cells using a micropatterned form of the single-cell gel electrophoresis comet assay. Cells from tissue or culture are loaded into thousands of microwells in an agarose chip, lysed, and electrophoresed so damaged DNA migrates out of each nucleus, then stained with a fluorescent DNA dye and imaged. It yields comet images from which damage measures such as percent tail DNA, tail length and tail moment are quantified for hundreds to thousands of cells per condition.', 'CometChip, comet assay, DNA strand break assay, genotoxicity assay, high-throughput comet, alkaline electrophoresis DNA damage, single cell gel electrophoresis, DNA damage assay, DNA strand break measurement, tail moment, cell-based assay, DNA repair assay, alkaline comet assay, neutral comet assay', 'Comet Chip', 'TIS or CEL', NULL, 'D.IMG or A.COMC', 'Processed', 'Raw', NULL, NULL, NULL, NULL, NULL, 138);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Computational Chemistry Simulation Data', 'This assay covers in silico calculation of molecular properties in place of a bench measurement. Structures are prepared and submitted to quantum chemical or molecular mechanics calculations such as density functional theory, docking or molecular dynamics, which return energies, optimized geometries, orbital properties and trajectories. Outputs are simulation files and derived descriptors, including binding energies, frontier orbital energies and ADMET style predictions, that can be compared against experimental results.', 'DFT calculation, quantum chemistry, molecular orbital, HOMO LUMO energy, ab initio calculation, computational molecular simulation, computational chemistry, molecular simulation, in silico chemistry, DFT simulation, molecular dynamics, reaction energy calculation, computational simulation, in silico data, molecular dynamics output, theoretical calculation, quantum chemistry output, density functional theory', 'Chemical Simulations, Simulation Data', 'CHM', NULL, 'D.SIM', 'Source', 'Raw', NULL, NULL, NULL, NULL, NULL, 101);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Computational Modeling', 'This assay builds mathematical, statistical and machine learning models from measured data. Curated measurements such as spectroscopic results, water quality readings or organ-on-a-chip observations are used to specify, fit and tune a model, whose structure and fitted parameters are kept with the runs used to train it. Outputs are model objects and simulation results that predict behavior beyond the measured conditions and expose the mechanisms implied by the fit.', 'computational model, mathematical model, in silico model, predictive modeling, systems biology model, simulation framework, model building, computational model generation, machine learning model training, predictive model development, model architecture, computational modeling, computational modelling, mechanistic model, ODE model, Modeling', 'Model Creation, Predictive Modeling', 'A.SPC or D.WTR or OOC', NULL, 'MDL or D.SIM', 'Analyzed', 'Analyzed', NULL, NULL, NULL, NULL, NULL, 100);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Convolutional Neural Network (CNN) Assay', 'This assay trains and applies convolutional neural networks to imaging data. Labeled images are split into training, validation and test sets, preprocessed and augmented, and used to fit a network such as a U-Net or ResNet, with performance tracked on held-out data. Outputs are the trained model together with its predictions, which may be class probabilities, regression values, segmentation masks or per-image scores.', 'CNN assay, deep learning assay, image classification model, neural network analysis, convolutional network, computer vision analysis, machine learning, deep learning, CNN, convolutional neural network, U-Net, ResNet', 'Convolutional Neural Network', 'D.IMG', NULL, 'M.CNN', 'Raw', 'Analyzed', NULL, NULL, NULL, NULL, NULL, 148);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Copy Number Variation Analysis', 'Copy Number Variation (CNV) analysis is performed using bulk DNA sequencing to detect and quantify genomic amplifications, deletions, and other structural alterations across the genome. Genomic DNA is extracted from bulk cell populations, subjected to library preparation, and sequenced using high-throughput next-generation sequencing (NGS) platforms. Sequencing read depth and coverage uniformity are analyzed computationally to identify regions of aberrant copy number relative to a reference, enabling the characterization of somatic or germline CNVs at a genome-wide scale.', 'CNV analysis, copy number alteration, CNA, genomic amplification deletion, structural variant, somatic copy number, genome-wide copy number, sequencing analysis, CNV, copy number estimation, CNV calling, CNVkit, aneuploidy, copy number profiling', NULL, 'D.SEQ', NULL, 'A.CNV', 'Raw', 'Analyzed', NULL, NULL, NULL, NULL, NULL, 20);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('cyCIF Analysis', 'This is the computational step that turns cyclic immunofluorescence image cycles into single-cell measurements. Raw multichannel tiles from each staining round are registered, stitched and background corrected, then cells are segmented and per-cell marker intensities extracted, commonly with pipelines such as MCMICRO. The output is a single-cell table of marker expression with spatial coordinates, used for cell typing, co-expression and neighborhood analysis.', 'cyCIF analysis, cyclic immunofluorescence analysis, multiplexed imaging analysis, iterative IF analysis, spatial protein quantification, tissue IF cycling, image analysis, MCMICRO, t-CyCIF analysis, image registration, single-cell marker quantification', NULL, 'D.IMG', NULL, 'A.CYCF', 'Raw', 'Analyzed', NULL, NULL, NULL, NULL, NULL, 180);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Cyclic Immunofluorescence (CyCIF)', 'Cyclic Immunofluorescence (CyCIF) is a multiplexed immunofluorescence imaging assay that enables the sequential detection of numerous protein targets within fixed tissue sections or cultured cells through iterative cycles of antibody staining, fluorescence imaging, and signal inactivation. Each cycle involves the application of fluorescently labeled primary or secondary antibodies, followed by wide-field or confocal microscopy image acquisition, and subsequent chemical or photo-bleaching of fluorophores to permit re-staining in successive rounds. The resulting multi-cycle images are computationally registered and integrated to generate high-dimensional, spatially resolved protein expression maps at single-cell resolution. This approach enables comprehensive characterization of cellular phenotypes, spatial organization, and tumor microenvironment composition within complex biological specimens.', 'CyCIF, cyclic immunofluorescence, t-CyCIF, iterative staining imaging, multiplexed fluorescence tissue, sequential antibody imaging, multiplexed tissue imaging, iterative IF staining, tissue cyclic staining, microscopy, immunofluorescence, multiplexed immunofluorescence, multiplex IF', 'CyCIF', 'TIS and AB or ABP', NULL, 'D.IMG or ABP', 'Processed', 'Raw', NULL, NULL, NULL, NULL, NULL, 122);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('CyTOF', 'Cytometry by Time of Flight (CyTOF) is a mass spectrometry-based single-cell analysis platform that enables simultaneous quantification of dozens of protein markers at the single-cell level by labeling antibodies with isotopically pure heavy metal tags rather than fluorescent dyes, thereby eliminating spectral overlap limitations inherent to conventional flow cytometry. Individual cells are introduced into an inductively coupled plasma ion source, vaporized and ionized, and the resulting metal isotope signals are detected and quantified by a time-of-flight mass spectrometer, providing precise measurements of marker expression across large cell populations. This technology is particularly suited for deep immunophenotyping, functional protein analysis, and characterization of complex cellular heterogeneity in samples such as peripheral blood, bone marrow, and tumor-infiltrating immune cells, supporting high-dimensional data analysis workflows including dimensionality reduction and unsupervised clustering approaches.', 'mass cytometry, CyTOF, metal-labeled antibody cytometry, high-dimensional cytometry, single cell protein profiling, HDCyto, time-of-flight mass spec cytometry, cytometry, cytometry by time of flight, Helios, Fluidigm, Standard BioTools, lanthanide-labeled antibodies', 'Mass Cytometry', 'TIS or CEL and AB', 'ABP', 'D.CYTOF or ABP or D.FLOW', 'Processed', 'Raw', NULL, NULL, NULL, NULL, NULL, 179);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('CyTOF Analysis', 'This step analyzes mass cytometry event data after acquisition. Files are bead normalized, debarcoded and compensated, then gated to remove debris and doublets, after which populations are defined by manual gating or by clustering and dimensionality reduction such as FlowSOM, PhenoGraph, viSNE or UMAP. Outputs are population frequencies, per-marker expression summaries and cluster assignments for each sample.', 'CyTOF analysis, mass cytometry analysis, high-dimensional clustering, viSNE, UMAP mass cytometry, metal-tag cytometry analysis, single cell protein analysis, cytometry analysis, FlowSOM, PhenoGraph, Cytobank, CATALYST, debarcoding, bead normalization', 'Mass Cytometry Analysis', 'D.CYTOF', NULL, 'A.CYTOF or A.FLOW', 'Raw', 'Analyzed', NULL, NULL, NULL, NULL, NULL, 178);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Dendritic Cell Preparation', 'Dendritic cell preparation generates dendritic cells from peripheral blood monocytes or bone marrow precursors for use in functional immune assays. Precursors are isolated and cultured in cytokine-supplemented media, typically with GM-CSF and IL-4, and may then be matured with defined stimuli. The prepared cells are checked for viability, yield and surface markers such as CD11c, MHC class II and CD80 or CD86 by flow cytometry before use.', 'DC preparation, dendritic cell generation, monocyte-derived dendritic cells, MDDC, antigen-presenting cell prep, DC maturation, cell culture, moDC, BMDC, bone marrow-derived dendritic cells, DC differentiation, dendritic cell culture', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 167);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Device Assembly', 'Device assembly builds an electrochemical filter device from its materials, such as conductive porous electrodes and a housing. A device can also be rebuilt from an earlier device.\nInput: Chemical materials (CHM), optionally an earlier device (FLT)\nOutput: Filter device (FLT).', 'device assembly, device fabrication, filter assembly, electrode fabrication, electrochemical filter, device build, filter fabrication, porous electrode, filter housing, electrofilter, filter device', NULL, 'CHM', 'FLT', 'FLT', 'Source', 'Source', NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Device Design', 'Device design records the computer-aided design (CAD) models and 3D-print files that define a device as designed, such as an electrochemical filter housing.\nInput: Filter device (FLT)\nOutput: Design and CAD files (D.CAD).', 'device design, CAD, computer-aided design, 3D printing, STL, SolidWorks, filter design, device model, electrochemical filter, CAD model, 3D model, 3D print file, design file', NULL, 'FLT', NULL, 'D.CAD', 'Source', 'Raw', NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Device Imaging', 'Device imaging captures microscopy images of microfluidic organ-on-a-chip devices and their contents while the device is in use. Chips are imaged on brightfield, epifluorescence or confocal systems, often as channel stacks or time series, to record cell position, vascular network structure, barrier integrity and reporter signal in each region of the device. It yields image files per device and timepoint that support later quantification of morphology, perfusion and cell behavior.', 'microfluidic device imaging, chip imaging, OOC imaging, organ-on-chip microscopy, lab-on-chip visualization, microscopy, organ-on-chip imaging, on-chip imaging, OOC microscopy, microvasculature imaging, confocal chip imaging', 'Microfluidic Device Imaging', 'OOC or AB', NULL, 'D.IMG', 'Processed', 'Raw', NULL, NULL, NULL, NULL, NULL, 37);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Digitally barcoded Mycobacterium tuberculosis barcode amplicon sequencing (barcode-by-sample count matrix)', 'This assay quantifies the relative abundance and dynamics of Mycobacterium tuberculosis strains that have been labeled with unique digital DNA barcodes, producing a barcode-by-sample count matrix for assessment of strain fitness, dissemination, or treatment response. It employs targeted PCR amplification of barcode loci from extracted bacterial genomic DNA followed by next-generation sequencing and read-mapping to a reference barcode library. Sample preparation and SOP steps include DNA extraction and library amplification/cleanup on standard molecular biology equipment (thermocycler, fluorometer/fragment analyzer) and computational demultiplexing, mapping, and normalization to generate the final barcode count matrix for downstream statistical analysis.', 'MTB barcode sequencing, tuberculosis barcode amplicon, barcode count matrix, Mtb population dynamics, barcoded strain tracking, MTB barcode analysis, tuberculosis barcode sequencing, Mtb lineage tracking, barcode amplicon sequencing, digitally barcoded bacteria, sequencing analysis, barcoded Mtb, amplicon sequencing, barcode abundance, Mycobacterium tuberculosis barcoding', 'Digitally Barcoded Mtb Matrix Analysis', 'D.SEQ', NULL, 'A.DBMM', 'Raw', 'Analyzed', NULL, NULL, NULL, NULL, NULL, 140);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('DNA Extraction', 'DNA extraction isolates and purifies DNA from bacteria, cultured cells or tissue so it can be used in sequencing, genotyping and amplification assays. Samples are lysed, proteins and other contaminants are removed, and nucleic acid is recovered on silica columns, on magnetic beads or by organic extraction, then eluted in buffer. Yield and purity are checked by fluorometric or spectrophotometric measurement and by absorbance ratios before the DNA is released for downstream work.', 'DNA isolation, genomic DNA extraction, gDNA extraction, nucleic acid extraction, DNA purification, QIAamp extraction, sample preparation, DNeasy, phenol-chloroform DNA extraction, gDNA isolation, DNA extraction kit, magnetic bead DNA extraction', 'cDNA Isolation', 'BAC or CEL or TIS or DNA', NULL, 'DNA or BAC', 'Source', 'Processed', NULL, NULL, NULL, NULL, NULL, 24);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Electrochemical Filtration', 'Electrochemical filtration passes a water sample through an electrochemical filter device held at an applied potential, to remove or transform contaminants. Each run produces a treated water sample that derives from both the input water and the filter used.\nInput: Water sample (WTR) and filter device (FLT)\nOutput: Treated water sample (WTR).', 'electrochemical filtration, electrofiltration, electrochemical water treatment, carbon nanotube filter, CNT filter, flow-through electrode, water treatment, contaminant removal, water quality, electrochemistry, water purification, nitrate reduction, flow-through filtration, applied potential', NULL, 'WTR and FLT', NULL, 'WTR', 'Source', 'Source', NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Electrochemical Sensor Assay', 'This assay employs electrochemical sensing technology to detect and quantify target analytes through measurement of electrochemical signals (e.g., current, voltage, or impedance) generated at a functionalized electrode surface. Samples are prepared and applied to the electrochemical sensor platform, where analyte-electrode interactions produce measurable electrical responses that are recorded and analyzed using dedicated instrumentation and data acquisition software. The electrochemical data are then calibrated and interpreted as analyte concentrations or binding events.', 'electrochemical assay, sensor measurement, amperometric assay, voltammetric assay, impedance assay, biosensor calibration, electrochemical sensor testing, biosensor testing, sensor sensitivity, sensor calibration, amperometric testing, voltammetric testing, electrochemistry, electrochemical impedance spectroscopy, EIS', 'Electrochemical Sensor Testing', 'CHM and SNSR', NULL, 'D.SNSR', 'Source', 'Raw', NULL, NULL, NULL, NULL, NULL, 113);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Electron Paramagnetic Resonance (EPR) Spectroscopy', 'Electron Paramagnetic Resonance (EPR) spectroscopy is employed to detect and characterize paramagnetic species, including free radicals, radical intermediates, and transition metal complexes, within biological or chemical samples. This technique measures the absorption of microwave radiation by unpaired electrons in the presence of an external magnetic field, providing information on the identity, concentration, and electronic environment of paramagnetic centers. Samples are prepared under controlled conditions to preserve radical species and analyzed using an EPR spectrometer, with spectral data processed to extract parameters such as g-values, hyperfine coupling constants, and spin concentration. The spectra are used to study oxidative stress, metalloprotein activity or reaction mechanisms.', 'EPR spectroscopy, ESR spectroscopy, electron paramagnetic resonance, spin label, radical detection, paramagnetic characterization, EPR, ESR, electron spin resonance, paramagnetic spectroscopy, free radical detection, unpaired electron measurement, spectroscopy, spin trapping, X-band EPR', 'Electron Paramagnetic Resonance', 'CHM', NULL, 'D.PRM', 'Source', 'Raw', NULL, NULL, NULL, NULL, NULL, 158);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('ELISA', 'This assay employs an enzyme-linked immunosorbent assay (ELISA) methodology to quantitatively detect and measure specific analytes (such as proteins, antibodies, or other biomolecules) in biological samples. The technique utilizes antibody-antigen interactions coupled with enzymatic signal amplification to generate colorimetric or fluorometric readouts proportional to analyte concentration. Sample preparation, incubation conditions, wash steps, and detection reagents are performed according to standardized protocols, with absorbance or fluorescence values measured using a microplate reader and quantified against a calibration curve.', 'enzyme-linked immunosorbent assay, ELISA, sandwich ELISA, plate-based immunoassay, OD measurement, absorbance immunoassay, microplate reader assay, immunoassay, indirect ELISA, competitive ELISA, direct ELISA, EIA, enzyme immunoassay, cytokine ELISA', NULL, 'AB or ABP and CEL or TIS', 'CHM', 'D.ELSA or ABP', 'Processed', 'Raw', NULL, NULL, NULL, NULL, NULL, 26);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Environmental sample collection', 'This assay describes the systematic collection of samples from non-biological environmental sources, such as water samples obtained from drinking water distribution systems or other geographic locations. The process establishes a hierarchical relationship between a parent sample type representing a geographic location (LOC) and a child sample type representing the collected environmental material (e.g., WTR for water), enabling spatial tracking and traceability of collected specimens. No biological extraction or analytical instrumentation is applied at this stage.', 'environmental sampling, field collection, water sampling, environmental monitoring, soil sampling, field sample collection, water sample collection, drinking water sampling, tap water sampling, grab sampling, sampling site, distribution system sampling', 'Sample Collection', 'LOC', NULL, 'WTR', 'Source', 'Source', NULL, NULL, NULL, NULL, NULL, 161);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('FC Receptor Binding Analysis', 'This step analyzes raw Fc receptor binding measurements. Signals across the dilution or concentration series are background corrected and fitted to obtain relative binding levels, affinities or kinetic parameters for each antibody sample and receptor in the panel, with normalization that allows comparison across plates and runs. Outputs are per-sample binding tables covering the Fc gamma receptors tested, used to describe antibody effector potential.', 'Fc receptor binding analysis, FcR binding analysis, Fc-gamma receptor binding, antibody effector function, receptor affinity analysis, FCRB analysis, Fc receptor data analysis, binding curve analysis, affinity quantification, effector function analysis, systems serology analysis, FcγR binding analysis, FcgR binding analysis', 'FC Receptor Binding Assay Analysis', 'D.FCRB', NULL, 'A.FCRB', 'Raw', 'Analyzed', NULL, NULL, NULL, NULL, NULL, 177);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Fc Receptor Binding Assay', 'This assay evaluates the binding affinity and interaction of test compounds or biological molecules (such as antibodies or Fc-fusion proteins) to Fc receptors (FcRs), which are critical mediators of immune effector functions including antibody-dependent cellular cytotoxicity (ADCC) and phagocytosis. Binding interactions are quantified using established biochemical or biophysical detection methodologies, enabling characterization of Fc-FcR engagement relevant to the functional activity of immunoglobulins or Fc-containing therapeutics. Results support structure-activity analysis and the development of antibody-based therapeutics.', 'Fc receptor binding assay, FcR binding, Fc-gamma receptor assay, FCRB assay, antibody effector function assay, receptor affinity measurement, systems serology, FcγR binding, FcgR binding, FCRB, Fc array, FcRn binding', NULL, 'TIS', NULL, 'D.FCRB', 'Processed', 'Raw', NULL, NULL, NULL, NULL, NULL, 27);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Field Water Quality Sensor Measurement', 'This assay monitors and records real-time physicochemical parameters of water samples or environmental water bodies using field-deployed sensor instrumentation. Measured parameters typically include but are not limited to temperature, pH, dissolved oxygen, conductivity, turbidity, and/or salinity, depending on the sensor array deployed. Data are collected in situ using portable or submersible multi-parameter probes, with readings logged at defined intervals according to field sampling protocols. Results support environmental water quality assessment, hydrological monitoring, or field-based research applications.', 'water quality sensor, field water measurement, in-situ water monitoring, drinking water sensor measurement, field water chemistry, water sensor run, field sensor deployment, in-situ water sensing, environmental water monitoring, aquatic sensor data, water quality, multiparameter sonde, dissolved oxygen, turbidity, salinity', 'Field Water Sensor Run', 'LOC', NULL, 'D.SNSR', 'Source', 'Raw', NULL, NULL, NULL, NULL, NULL, 147);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Flow Cytometry', 'Flow cytometry is a laser-based, high-throughput single-cell analysis technique used to simultaneously measure multiple physical and fluorescent characteristics of cells or particles in suspension. This assay quantifies cell populations based on parameters such as cell size (forward scatter), granularity (side scatter), and fluorescence intensity of labeled surface or intracellular markers, enabling immunophenotyping, cell cycle analysis, viability assessment, and functional studies. Samples are typically prepared as single-cell suspensions, stained with fluorochrome-conjugated antibodies or dyes, and acquired on a flow cytometer, with subsequent data analysis performed using dedicated software (e.g., FlowJo, FCS Express) to gate and enumerate distinct cellular subpopulations.', 'flow cytometry, FACS, immunophenotyping, cell surface marker staining, fluorescence cytometry, multi-parameter cell analysis, cell population profiling, cytometry, flow cytometer, spectral flow cytometry, Cytek Aurora, intracellular cytokine staining, ICS, multicolor flow cytometry, LSRFortessa', NULL, 'TIS or CEL, AB or ABP', 'D.FCS or D.FLOW', 'D.FLOW or CEL or A.FLOW or D.FCS or ABP', 'Processed', 'Raw', NULL, 'ImmPort', 'TIS::Type, ABP::Parent, D.FLOW::Stimulation, D.FLOW::Protocol, D.FLOW::Parent', NULL, NULL, 30);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Flow Cytometry Analysis', 'Flow cytometry analysis interprets acquired event data rather than staining or running samples. Compensation is applied, quality gates remove debris and doublets, and a defined gating strategy is used to identify populations of interest, commonly in FlowJo, OMIQ or FCS Express. Outputs are population frequencies, absolute counts where counting beads are used, and per-marker intensity statistics for each sample.', 'flow cytometry analysis, FACS analysis, gating analysis, cell population analysis, FlowJo analysis, FCS Express, immunophenotyping analysis, gating, gating strategy, FlowJo, OMIQ, compensation, FCS file analysis', 'Flow Cytometry Processing', 'D.FLOW or NHP', NULL, 'A.FLOW', 'Raw', 'Analyzed', NULL, NULL, NULL, NULL, NULL, 31);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Fourier Transform Infrared Spectroscopy (FTIR)', 'Fourier Transform Infrared (FTIR) Spectroscopy is an analytical technique that measures the absorption of infrared light by molecular bonds within a sample, providing a characteristic spectral fingerprint that reflects the biochemical composition of biological materials, including proteins, lipids, carbohydrates, and nucleic acids. Infrared spectra are acquired across a defined wavenumber range as absorbance or transmittance data. Spectral preprocessing steps typically include baseline correction, normalization, and noise reduction, followed by multivariate or chemometric analysis to extract biologically meaningful information from the high-dimensional spectral datasets.', 'FTIR spectroscopy, infrared spectroscopy, attenuated total reflectance, ATR-FTIR, molecular fingerprint, chemical bond analysis, FTIR, IR spectroscopy, molecular vibration, chemical fingerprint, functional group analysis, mid-IR spectroscopy, spectroscopy, vibrational spectroscopy, FT-IR', 'Fourier Transform Infrared Spectroscopy', 'TIS or CEL', NULL, 'D.SPC', 'Processed', 'Raw', NULL, NULL, NULL, NULL, NULL, 166);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Gel Permeation Chromatography (GPC)', 'Gel permeation chromatography separates polymers and other macromolecules by hydrodynamic volume to describe their molecular weight distribution. Samples are dissolved, filtered and injected onto porous columns calibrated with molecular weight standards, with elution followed by refractive index, ultraviolet or light scattering detection. It yields chromatograms from which number-average and weight-average molecular weights and dispersity are calculated.', 'GPC, SEC, size exclusion chromatography, molecular weight distribution, polymer characterization, hydrodynamic volume separation, polymer size separation, chromatography fractionation, chromatography, dispersity, polydispersity index, number-average molecular weight, weight-average molecular weight, SEC-MALS', 'Gel Permeation Chromatography', 'CHM', NULL, 'D.GPC', 'Source', 'Raw', NULL, NULL, NULL, NULL, NULL, 156);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Gene Expression Analysis', 'Gene expression analysis converts raw sequencing reads into quantified transcript abundance. It involves aligning reads to a reference genome or transcriptome, followed by normalization and quality control.\nInput: Sequencing file (e.g., FASTQ / D.SEQ)\nOutput: Processed expression matrices and summary statistics.', 'RNA-seq analysis, differential expression analysis, DESeq2, edgeR, count matrix processing, transcriptomics analysis, STAR, kallisto, salmon, gene expression validation, validation data, sequencing analysis, bulk RNA-seq analysis, differential gene expression profiling, transcript quantification', 'Gene Expression Validation Assay', 'D.SEQ', NULL, 'A.GEX', 'Raw', 'Analyzed', NULL, 'GEO', 'A.GEX::Parent, A.GEX::Protocol', NULL, NULL, 99);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Genome Alignment', 'This assay involves the computational alignment of sequencing reads to a reference genome, enabling the mapping of raw sequence data to genomic coordinates for downstream variant calling, expression quantification, or structural analysis. Sequencing data files (e.g., FASTQ) are processed using standard bioinformatic alignment tools (such as BWA, STAR, or Bowtie2) to produce aligned output files (e.g., BAM/SAM format), which are subsequently sorted, indexed, and subjected to quality control assessment.', 'read alignment, sequence mapping, reference genome alignment, BWA, STAR, Bowtie, BAM generation, read mapping, NGS alignment, sequencing analysis, BWA-MEM, Bowtie2, STAR aligner, HISAT2, sequence alignment, BAM file', NULL, 'D.SEQ', NULL, 'A.ALN or A.GEX', 'Raw', 'Analyzed', NULL, 'GEO, SRA', NULL, NULL, NULL, 34);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Glycosylation Assay', 'This assay characterizes the glycosylation profile of biological samples by analyzing the composition, structure, and abundance of glycan moieties attached to proteins or other biomolecules. Standard glycosylation analysis workflows typically involve sample preparation steps such as enzymatic release of N-linked glycans (e.g., via PNGase F treatment), followed by labeling or derivatization and separation using chromatographic or electrophoretic techniques (such as HPLC, UHPLC, or capillary electrophoresis) coupled with fluorescence or mass spectrometric detection. Downstream analysis quantifies individual glycan species, calculates derived glycosylation traits and assesses batch or sample quality. Results support characterization of glycan heterogeneity and may be used to monitor biological processes, product quality attributes, or disease-associated glycosylation changes.', 'glycan analysis, sugar modification analysis, N-glycan profiling, O-glycan analysis, antibody glycosylation, glycoproteomics, carbohydrate characterization, systems serology, glycomics, Fc glycosylation, IgG glycosylation, PNGase F, fucosylation, galactosylation, sialylation', NULL, 'AB', NULL, 'D.GLYN', 'Source', 'Raw', NULL, NULL, NULL, NULL, NULL, 155);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('GPT Assay', 'The GPT assay covers two measurements recorded under the same name. In the gpt delta transgenic mutation assay, genomic DNA is extracted from tissue of transgenic animals, the gpt transgene is rescued by lambda phage packaging, and mutants are selected as 6-thioguanine resistant colonies, giving a mutant frequency of resistant over total rescued colonies and clones that can be sequenced for their mutation spectrum. The name is also used for the alanine aminotransferase activity assay, in which the enzyme also called glutamate pyruvate transaminase is measured in serum or tissue as a marker of liver injury.', 'ALT assay, GPT assay, alanine aminotransferase, liver enzyme assay, hepatotoxicity marker, transaminase activity, liver function test, glutamate pyruvate transaminase, phage efficiency assay, plaque assay, phage titer, gpt delta, transgenic mutation assay, mutant frequency, 6-thioguanine selection, in vivo mutagenesis, gpt mutation assay, transgenic rodent mutation assay', 'Alanine Aminotransferase (ALT/GPT) Activity Assay', 'TIS or DNA', NULL, 'D.GPT', 'Processed', 'Raw', NULL, NULL, NULL, NULL, NULL, 143);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Hierarchical Clustering', 'Hierarchical clustering is an unsupervised machine learning method that organizes data points into nested, hierarchical groupings based on pairwise distance or similarity metrics (e.g., Euclidean or Manhattan distance), without requiring a predetermined number of clusters. The algorithm proceeds either agglomeratively (bottom-up, iteratively merging the closest clusters) or divisively (top-down, recursively splitting the most heterogeneous cluster), with inter-cluster distances defined by a chosen linkage criterion such as single, complete, average, or Ward\'s minimum variance linkage. Results are visualized as a dendrogram, from which discrete clusters are derived by applying a threshold cut at an appropriate hierarchical level. This approach is widely employed in biomedical and bioinformatics contexts, including gene expression profiling, multi-omics data integration, and patient stratification, to reveal inherent structure and co-expression or co-occurrence patterns within complex, high-dimensional datasets.', 'hierarchical clustering, dendrogram, agglomerative clustering, Ward linkage, cluster analysis, unsupervised clustering, statistics, hclust, clustered heatmap, average linkage, complete linkage, distance matrix', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 159);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Histopathology', 'Histopathology prepares and stains tissue so its microscopic structure can be examined. Specimens are fixed, embedded, sectioned and stained with hematoxylin and eosin or a special stain such as trichrome or PAS, then imaged by light microscopy or whole slide scanning. It yields stained slide images showing tissue architecture, cellular morphology and pathological features such as inflammation, necrosis and fibrosis.', 'histopathology, H&E staining, tissue staining, pathological examination, tissue morphology, hematoxylin eosin, histological analysis, microscopy, H&E, hematoxylin and eosin, trichrome staining, PAS staining, histochemistry, pathology slides, Histology', NULL, 'TIS', NULL, 'D.IMG', 'Processed', 'Raw', NULL, NULL, NULL, NULL, NULL, 145);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Histopathology Analysis', 'Histopathology analysis is the evaluation step applied to stained tissue slide images. A pathologist or an image analysis tool such as QuPath or HALO reviews the images and records findings as scores and measurements, covering features such as lesion burden, inflammation, necrosis and fibrosis. Outputs are per-slide or per-animal scoring tables, with annotated regions where digital analysis is used.', 'histopathology analysis, digital pathology, tissue image analysis, H&E analysis, pathological scoring, slide analysis, image analysis, QuPath, HALO, whole slide image analysis, lesion scoring, histological scoring, histology analysis', NULL, 'D.IMG', NULL, 'A.IMG', 'Raw', 'Analyzed', NULL, NULL, NULL, NULL, NULL, 187);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Imaging', 'This assay covers general image acquisition on cells, tissue, antibody preparations and chemical samples. Specimens are prepared and imaged by light microscopy, including brightfield, phase contrast, epifluorescence and confocal modes, with acquisition settings chosen for the feature of interest. It yields image files that record morphology, spatial arrangement and fluorescence signal for later quantitative or qualitative analysis.', 'microscopy, imaging assay, optical imaging, fluorescence imaging, confocal imaging, brightfield imaging, image acquisition, light microscopy, widefield microscopy, fluorescence microscopy, epifluorescence microscopy', NULL, 'CEL or CHM or TIS or AB', NULL, 'D.IMG', 'Processed', 'Raw', NULL, NULL, NULL, NULL, NULL, 36);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Imaging Analysis', 'Imaging analysis processes raw image data to extract measurements or visual patterns. It includes segmentation, quantification, and visualization of spatial features.\nInput: Raw imaging data\nOutput: Processed image metrics and annotated visualizations.', 'image analysis, image processing, image quantification, morphology analysis, segmentation analysis, pixel quantification, computer vision analysis, cell image analysis, culture image processing, morphology quantification, cell growth analysis, confluence analysis, ImageJ, Fiji, CellProfiler', 'Image Analysis, Cell Culture Imaging Analysis, Cell Imaging Analysis', 'D.IMG', NULL, 'A.IMG', 'Raw', 'Analyzed', NULL, NULL, NULL, NULL, NULL, 118);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Immunohistochemistry', 'Immunohistochemistry (IHC) is a histological technique that detects and localizes specific proteins or antigens within tissue sections through the use of labeled antibodies, enabling assessment of protein expression, distribution, and abundance in a spatially resolved context. Tissue samples are typically fixed, embedded, sectioned, and subjected to antigen retrieval prior to incubation with primary and secondary antibodies conjugated to detectable reporters such as enzymatic or fluorescent labels. Image acquisition and analysis are performed to quantify staining intensity, cellular localization, and expression patterns across tissue regions.', 'IHC, immunostaining, antibody tissue staining, protein localization tissue, chromogenic IHC, DAB staining, fluorescent IHC, microscopy, gammaH2AX staining, γH2AX, cleaved caspase-3 staining, IHC-P, antigen retrieval', NULL, 'TIS', 'AB', 'D.IMG', 'Processed', 'Raw', NULL, NULL, NULL, NULL, NULL, 141);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Immunopeptidomics', 'Immunopeptidomics identifies the peptides presented on MHC molecules by cells or tissue. MHC-peptide complexes are captured from lysates by immunoaffinity purification, the bound peptides are eluted and cleaned up, separated by liquid chromatography and measured by tandem mass spectrometry. It yields raw spectra of the presented peptide repertoire, used to map naturally processed epitopes in cancer immunology, vaccine and autoimmunity studies.', 'immunopeptidomics, MHC-I MHC-II peptide, HLA peptide profiling, antigen presentation, neoantigen identification, immune peptide mass spec, immunopeptideomics, MHC peptidome, HLA ligandome, antigen presentation profiling, neoantigen, immune peptide identification, mass spectrometry, peptidomics, HLA peptidomics', 'ImmunoPeptideomics', 'TIS or CEL', NULL, 'D.MSP', 'Processed', 'Raw', NULL, 'PRIDE', NULL, NULL, NULL, 169);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Intravital Microscopy', 'Intravital microscopy (IVM) is an advanced imaging technique used to visualize and quantify dynamic biological processes in living animals in real time, including cellular behavior, vascular dynamics, immune cell trafficking, and tissue interactions at the microscopic level. The method employs high-resolution optical microscopy platforms, such as confocal, two-photon, or widefield fluorescence microscopes, coupled with appropriate surgical preparation or optical window chambers to provide direct access to tissues of interest (e.g., tumor microenvironment, lymph nodes, liver, or vasculature). Fluorescently labeled cells, proteins, or dyes are introduced into the living subject, and time-lapse image sequences are acquired to track parameters such as cell migration velocity, vessel permeability, leukocyte rolling and adhesion, or reporter gene expression. Quantitative image analysis is subsequently performed using specialized software to extract spatiotemporal metrics from the acquired datasets.', 'intravital imaging, in vivo microscopy, two-photon microscopy, live animal imaging, in vivo fluorescence microscopy, microscopy, IVM, multiphoton microscopy, imaging window, confocal intravital imaging', NULL, 'MUS', NULL, 'D.IMG', 'Source', 'Raw', NULL, NULL, NULL, NULL, NULL, 163);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Ion Chromatography', 'Ion chromatography separates and detects ionic species in a sample, such as nitrite and nitrate, by passing it through an ion-exchange column and recording conductivity over time. The run produces raw detector exports for later calibration against standards.\nInput: Water sample (WTR)\nOutput: Raw ion chromatography data (D.ICM).', 'ion chromatography, IC, ion exchange chromatography, anion analysis, nitrate, nitrite, conductivity detection, water chemistry, water quality, chromatography, Dionex, anion chromatography, chromatogram, ion analysis', NULL, 'WTR', NULL, 'D.ICM', 'Source', 'Raw', NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Ion Chromatography Analysis', 'Ion chromatography analysis converts raw ion chromatography exports into concentrations by calibration against standards, and derives quantities such as nitrite and nitrate conversion.\nInput: Raw ion chromatography data (D.ICM)\nOutput: Ion concentrations and conversions (A.ICM).', 'ion chromatography analysis, IC calibration, standard curve, nitrate quantification, nitrite quantification, ion concentration, water quality analysis, calibration curve, chromatogram analysis, peak integration, Chromeleon, nitrate conversion, nitrite conversion', NULL, 'D.ICM', NULL, 'A.ICM', 'Raw', 'Analyzed', NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('iPSC Chondrogenic Differentiation and Chondronoid Formation', 'This assay maintains induced pluripotent stem cells and differentiates them into chondronoids, cartilage-like three-dimensional constructs. iPSCs are expanded under defined pluripotency conditions, then taken through staged chondrogenic induction with media and growth factor changes over a set culture period. The resulting chondronoids are assessed for cartilage matrix deposition and cellular organization, and serve as an in vitro model of chondrogenesis and cartilage biology.', 'iPSC differentiation, chondrogenesis, chondronoid, stem cell cartilage, induced pluripotent stem cell, cartilage organoid, iPSC chondrocyte, iPSC culture, chondronoid formation, stem cell 3D culture, induced pluripotent stem cell culture, cell culture, stem cell differentiation, chondrocyte differentiation, hiPSC', 'iPSC Culture and Chondronoid Formation, iPSC Culture and Chrondronoid Formation', 'CEL', NULL, 'CEL', 'Source', 'Source', NULL, NULL, NULL, NULL, NULL, 95);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Library Creation', 'Library creation converts extracted nucleic acid into indexed libraries that a sequencer can read. Most start from RNA for RNA-seq, which is reverse transcribed to complementary DNA before fragmentation, end repair, adapter ligation and amplification; DNA inputs enter the same workflow directly, and DNA-barcoded antibody panels, as used in CITE-seq, are turned into libraries the same way. Libraries are quantified and size checked before pooling, and the pooled library is what sequencing consumes.', 'sequencing library creation, library construction, NGS library, adapter ligation, library prep, sequencing input preparation, library preparation, sequencing library, NGS library prep, sequencing input, Nextera library, fragmentation library prep, sequencing, TruSeq, RNA-seq library prep', 'Library Prep, Library Preparation, Extraction and Library Creation', 'RNA or DNA or CEL or ABP', NULL, 'DNA', 'Processed', 'Processed', NULL, NULL, NULL, NULL, NULL, 115);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Linear Mixed Model', 'This assay fits linear mixed models to measured data to separate fixed effects of interest from random variation. Repeated or hierarchically structured measurements, such as titers, Fc receptor binding or phagocytosis readouts collected across subjects and timepoints, are modeled with subject or batch level random effects, usually with lme4 or an equivalent library. Outputs are fitted model objects with effect estimates, variance components, confidence intervals and significance tests.', 'LMM, linear mixed model, mixed effects model, random effects model, REML, repeated measures model, longitudinal statistical model, statistics, linear mixed-effects model, lme4, mixed model, multilevel model, hierarchical linear model', NULL, 'D.TITR or D.FCRB or D.ADCP or D.ADNP or A.MSP', NULL, 'M.LMM', 'Analyzed', 'Analyzed', NULL, NULL, NULL, NULL, NULL, 144);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Long-Read Sequencing', 'Long read sequencing is a next-generation sequencing approach that generates nucleic acid sequence reads typically exceeding 10 kilobases in length, enabling the detection of complex genomic features such as structural variants, repetitive elements, full-length transcript isoforms, and phased haplotypes that are difficult to resolve with short-read technologies. This methodology employs platforms such as Pacific Biosciences (PacBio) Single Molecule Real-Time (SMRT) sequencing or Oxford Nanopore Technologies (ONT) sequencing, which capture sequence information from single DNA or RNA molecules in real time. Sample preparation generally involves high-molecular-weight nucleic acid extraction, library construction with minimal fragmentation, and size selection to preserve long fragments prior to sequencing. Resulting data are analyzed using specialized bioinformatic pipelines for base calling, alignment to reference genomes, and downstream variant or isoform detection, providing comprehensive insights into genome structure, epigenetic modifications, and transcriptome complexity.', 'long-read sequencing, Oxford Nanopore, PacBio SMRT, third-generation sequencing, long reads, nanopore sequencing, PacBio, SMRT, nanopore long reads, sequencing, ONT, MinION, PromethION, PacBio HiFi, Revio', 'Long Read Sequencing', 'DNA', NULL, 'D.SEQ', 'Processed', 'Raw', NULL, 'GEO, SRA', NULL, NULL, NULL, 77);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Luminex Data Processing', 'Luminex data processing converts raw bead-based immunoassay readouts into reportable analyte values. Median fluorescence intensities are background corrected and interpolated against a standard curve, typically a five-parameter logistic fit, with quality control on bead counts, standard recovery and replicate agreement, in software such as xPONENT or Bio-Plex Manager. The result is a table of analyte concentrations per sample with flags for values outside the quantifiable range.', 'Luminex data processing, multiplex immunoassay processing, MFI to concentration, cytokine quantification, Luminex plate analysis, Luminex analysis, multiplex data analysis, MFI analysis, cytokine analysis, bead-based assay analysis, standard curve analysis, immunoassay analysis, xPONENT, 5PL curve fit, Bio-Plex Manager', 'Luminex Analysis', 'D.LMX', NULL, 'A.LMX', 'Raw', 'Analyzed', NULL, NULL, NULL, NULL, NULL, 183);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Luminex Multiplex Immunoassay', 'A Luminex multiplex immunoassay measures many analytes in one small sample volume using color-coded capture beads. Cell extract, tissue or culture material is incubated with the bead panel, followed by a biotinylated detection antibody and a streptavidin-phycoerythrin reporter, and the beads are read individually on an instrument such as MAGPIX or FLEXMAP 3D. It yields raw median fluorescence intensity readings per bead region and well, which are later converted into concentrations against a standard curve.', 'Luminex multiplex, bead-based multiplex immunoassay, cytokine multiplex, xMAP immunoassay, MAGPIX assay, BioPlex assay, Luminex, xMAP, multiplex bead assay, cytokine panel, bead-based immunoassay, BioPlex, MAGPIX, MFI measurement, immunoassay', 'Luminex, Luminex Assay', 'CEX or TIS or CEL', NULL, 'D.LMX', 'Processed', 'Raw', NULL, NULL, NULL, NULL, NULL, 131);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Magnetic Resonance Imaging (MRI)', 'Magnetic Resonance Imaging (MRI) is a non-invasive imaging modality that utilizes strong magnetic fields and radiofrequency pulses to generate detailed anatomical and functional images of internal tissues and organs based on the nuclear magnetic resonance properties of hydrogen protons in biological samples. The technique enables visualization and quantification of structural morphology, tissue composition, and physiological parameters without the use of ionizing radiation. Image acquisition and reconstruction are performed using specialized pulse sequences tailored to the biological question of interest, with subsequent analysis involving segmentation, volumetric measurements, or signal intensity quantification using dedicated image analysis software.', 'MRI, magnetic resonance imaging, structural MRI, functional MRI, tissue MRI, brain MRI, NMR imaging, non-invasive imaging, tissue imaging, body MRI, NMR-based imaging, medical imaging, radiology, T1-weighted MRI, T2-weighted MRI', NULL, 'PAV', NULL, 'D.IMG', 'Source', 'Raw', NULL, NULL, NULL, NULL, NULL, 90);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('MALDI Mass Spectrometry Imaging (MALDI-MSI)', 'Matrix-Assisted Laser Desorption/Ionization Mass Spectrometry Imaging (MALDI-MSI) is a label-free spatial metabolomics and proteomics technique that enables the simultaneous detection and visualization of the distribution of small molecules, lipids, peptides, and proteins directly within tissue sections. The method involves mounting thin cryosectioned tissue slices onto conductive target plates, applying a UV-absorbing matrix compound that co-crystallizes with analytes, and then rastering a pulsed laser across the tissue surface to generate ions that are analyzed by a mass spectrometer. The resulting data provide spatially resolved mass spectra at each pixel position, allowing generation of ion intensity maps that correlate molecular identities with histological features across the tissue. Downstream analysis typically involves spectral preprocessing, normalization, and multivariate statistical approaches to identify regions of differential molecular composition.', 'MALDI-MSI, MALDI imaging, mass spectrometry imaging, spatial metabolomics, tissue ion imaging, molecular imaging MALDI, molecular imaging tissue, matrix-assisted laser desorption ionization imaging, mass spectrometry, MALDI, MSI, imaging mass spectrometry, MALDI-TOF imaging, lipid imaging, spatial lipidomics', 'MALDI-MSI', 'TIS or CEL', NULL, 'D.MSI', 'Processed', 'Raw', NULL, NULL, NULL, NULL, NULL, 92);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Mass Spectrometry', 'Mass spectrometry identifies and quantifies molecules by ionizing a sample and measuring the mass-to-charge ratios of the resulting ions. Chemical samples, water samples and DNA are introduced by liquid or gas chromatography or by direct infusion, and spectra are recorded across the mass range, including high resolution accurate mass runs on Orbitrap or QTOF instruments that support molecular formula assignment. It yields raw spectra and chromatograms describing the small molecules, metabolites and adducts present in the sample.\nInput: Prepared chemical, water or nucleic acid sample\nOutput: Mass spectrometry data file containing ion spectra.', 'LC-MS, mass spectrometry, MS/MS, tandem mass spec, mass-to-charge measurement, ion detection, mass spec analysis, small molecule mass spectrometry, metabolite detection, mass spec, metabolomics, GC-MS, untargeted metabolomics, MRM, DNA adducts, HRMS, high-resolution mass spectrometry, accurate mass determination, Orbitrap, QTOF, elemental composition, molecular formula confirmation, accurate mass, molecular formula, exact mass measurement, high resolution mass spec, Q-TOF, FT-ICR, ESI-HRMS', 'High Resolution Mass Spectrometry (HRMS), High Resolution Mass Spectra', 'CHM or WTR or DNA', NULL, 'D.SPC or D.MSP', 'Source', 'Raw', NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Mass Spectrometry Analysis', 'This step processes raw mass spectrometry data into quantified, annotated results. Peaks are detected, aligned across runs and calibrated, then features are annotated by accurate mass, isotope pattern and fragmentation against spectral libraries or theoretical values, which also covers high resolution work where molecular formulas are confirmed within a few parts per million. Outputs are quantification tables and annotated feature or compound lists ready for statistical comparison.\nInput: Raw mass spectrometry data (D.SPC or D.MSP)\nOutput: Processed quantification tables and annotated features.', 'mass spectrometry analysis, MS data processing, spectral analysis, small molecule quantification, metabolite quantification, feature annotation, metabolomics analysis, peak picking, XCMS, MZmine, MS-DIAL, Compound Discoverer, HRMS analysis, accurate mass analysis, molecular formula confirmation, high-resolution MS data processing, exact mass analysis, isotope pattern analysis, mass error ppm, Xcalibur, MassHunter, elemental composition analysis', 'High Resolution Mass Spectra Analysis, Mass Spectrometry Processing', 'D.SPC or D.MSP', NULL, 'A.SPC or A.MSP', 'Raw', 'Analyzed', NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Mass Spectrometry Proteomics', 'This assay uses mass spectrometry-based proteomics to identify and quantify the proteins in biological samples, through tandem mass spectrometry (MS/MS) workflows that typically include protein digestion, peptide separation by liquid chromatography and spectral acquisition. Proteins are identified and quantified by searching the acquired spectra against reference proteomes, including post-translational modifications.', 'proteomics, LC-MS/MS, shotgun proteomics, bottom-up proteomics, peptide mass fingerprinting, tandem MS proteomics, mass spectrometry proteomics, mass spectrometry, protein mass spectrometry, MS proteomics, data-independent acquisition, TMT, tandem mass tag, phosphoproteomics, quantitative proteomics', 'LC - MS/MS (Proteomics)', 'TIS or CEL or SLD or CEX or LYS or CHM', NULL, 'D.MSP', 'Processed', 'Raw', NULL, 'PRIDE', NULL, NULL, NULL, 130);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Mass Spectrometry Proteomics Analysis', 'Mass spectrometry proteomics analysis processes raw proteomics data to identify and quantify peptides and proteins. It performs database matching and normalization to generate protein-level abundance profiles.\nInput: Raw proteomics mass spectrometry data\nOutput: Processed protein quantification tables and annotated identifications.', 'proteomics data analysis, MaxQuant, Perseus, protein quantification, proteomics pipeline, peptide identification, protein identification, database search, label-free quantification, mass spectrometry proteomics analysis, Proteome Discoverer, Spectronaut, DIA-NN, FragPipe, phosphoproteomics analysis', 'Proteomics Analysis', 'D.MSP', NULL, 'A.MSP or A.PHP or A.IMP', 'Raw', 'Analyzed', NULL, 'PRIDE', NULL, NULL, NULL, 47);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Migration Assay Analysis', 'This assay evaluates the migratory capacity of cells under defined experimental conditions, quantifying movement through or across a barrier (such as a membrane or wound gap) as a measure of cellular motility and invasive potential. Standard methodologies may include scratch/wound-healing assays or Transwell-based migration chambers, with imaging and automated or manual analysis used to quantify migrated cell numbers or closure rates over time. The results support analyses of cell behavior in disease modeling, drug screening or mechanistic studies.', 'cell migration analysis, scratch assay analysis, wound healing analysis, transwell migration analysis, motility quantification, chemotaxis analysis, organ-on-chip analysis, migration analysis, cell tracking, cell velocity analysis, invasion assay analysis, TrackMate', NULL, 'D.IMG', NULL, 'A.MIGR', 'Raw', 'Analyzed', NULL, NULL, NULL, NULL, NULL, 80);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Model Validation', 'Model validation checks how well a fitted model performs on data it was not trained on. Predictions are compared against observed measurements using cross-validation, a held-out test set or an independent dataset, and performance is summarized with error and agreement metrics appropriate to the task. Outputs are validation results and the validated model, kept with the acceptance criteria and the data used to judge it.', 'model validation, model performance evaluation, model accuracy, cross-validation, model testing, generalization assessment, computational modeling, model evaluation, external validation, k-fold cross-validation, held-out test set, benchmarking', NULL, NULL, NULL, 'MDL', 'Analyzed', 'Analyzed', NULL, NULL, NULL, NULL, NULL, 102);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('MRI Analysis', 'MRI analysis is the interpretation step applied to acquired magnetic resonance image series. Images are registered, segmented and measured to derive quantitative parameters such as tissue and lesion volumes, signal intensities and structural dimensions, usually in tools such as FreeSurfer or 3D Slicer. Results are reported as per-subject measurement tables and annotated image overlays that support disease characterization and longitudinal comparison.', 'MRI image analysis, volumetric MRI analysis, tissue segmentation, radiological image analysis, brain volume analysis, medical image analysis, MRI segmentation, FreeSurfer, 3D Slicer, MRI volumetry', NULL, 'D.IMG', NULL, 'A.IMG', 'Raw', 'Analyzed', NULL, NULL, NULL, NULL, NULL, 176);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Multiplex Bead-Based Antibody Titer Panel Assay', 'The Titer Bead Panel Assay is a multiplexed Luminex-based immunoassay that consolidates multiple individual antibody (AB) titer measurements into a unified antibody panel (ABP) for comprehensive humoral immune profiling. Spectrally distinct fluorescent microspheres are each conjugated to a different antigen, allowing simultaneous quantification of antibody titers against multiple targets in a single sample. Serum or plasma is incubated with the bead mixture, and bound antibodies are detected with fluorescently labeled secondary antibodies. A Luminex flow analyzer identifies each bead by its spectral signature and quantifies bound antibody by reporter fluorescence intensity. Results are reported as median fluorescence intensity (MFI) or calculated titers for each antigen in the panel, enabling efficient multiplex characterization of antibody responses across vaccine antigens, pathogen variants, or serological panels.', 'multiplex titer panel, bead-based antibody titer, BAMA, binding antibody multiplex assay, antibody panel titer, multiplex serology, systems serology, titer bead panel, Luminex antibody titer, antigen-coupled microspheres, isotype subclass profiling, multiplexed Luminex serology', 'Titer Bead Panel Assay', 'AB', NULL, 'ABP', 'Source', 'Source', NULL, NULL, NULL, NULL, NULL, 105);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Mutational Spectra Analysis', 'This assay characterizes the mutational spectrum of biological samples by identifying and quantifying the types, frequencies, and patterns of mutations (such as base substitutions, insertions, and deletions) across a defined genomic region or whole genome. The analysis typically employs next-generation sequencing (NGS) or Sanger sequencing technologies, followed by bioinformatic processing to classify mutations by type (e.g., transitions, transversions) and context, enabling the construction of mutational signatures. Outputs may include mutation frequency tables, signature decomposition results and plots of the mutational landscape. Results are used to assess mutagenic potential, characterize mutagen exposure, or investigate DNA repair mechanisms in the experimental system under study.', 'mutation signature analysis, SBS signature, COSMIC signature, trinucleotide context, mutational landscape, mutagen characterization, sequencing analysis, mutational signatures, mutational spectrum, mutation spectrum, SigProfiler, base substitution spectrum', 'Mutational Spectral Analysis', 'D.SEQ', NULL, 'A.MUSP', 'Raw', 'Analyzed', NULL, NULL, NULL, NULL, NULL, 52);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Necropsy', 'Necropsy is the post-mortem examination of a study animal. The carcass is dissected under a standard scheme, gross findings and macroscopic lesions are described, organs are weighed, and tissues are collected and preserved for histology, molecular or microbiological work. It yields the recorded gross pathology together with the tissue samples that downstream assays consume.', 'animal necropsy, post-mortem examination, animal autopsy, dissection, pathological dissection, organ harvest post-mortem, in vivo, gross pathology, organ weights, terminal harvest, autopsy', 'NHP Necropsy, Mouse Necropsy', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 139);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Nuclear Magnetic Resonance Spectroscopy', 'Nuclear Magnetic Resonance (NMR) spectroscopy is employed to characterize the structural, chemical, and physical properties of molecules by detecting the resonance frequencies of atomic nuclei (typically ¹H, ¹³C, or other NMR-active nuclei) in a strong magnetic field. This assay provides quantitative and qualitative information on molecular identity, purity, conformation, and dynamics, and may be applied to small molecules, metabolites, proteins, or other biomolecules in solution or solid state.', 'NMR spectroscopy, proton NMR, 1H NMR, 13C NMR, metabolomics NMR, chemical structure NMR, magnetic resonance spectroscopy, spectroscopy, 2D NMR, HSQC, 31P NMR, 19F NMR, qNMR, NMR', 'Nuclear Magnetic Resonance', 'CHM', NULL, 'D.NMR', 'Source', 'Raw', NULL, NULL, NULL, NULL, NULL, 89);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Nuclear Magnetic Resonance Spectroscopy Analysis', 'This step processes and interprets raw NMR spectra rather than acquiring them. Free induction decay data are Fourier transformed, phased, baseline corrected and referenced, then peaks are picked, assigned and integrated to identify and quantify metabolites or to confirm chemical structure, using software such as TopSpin, MestReNova or Chenomx. The output is an assigned peak list with chemical shifts, couplings and concentrations or relative abundances.', 'NMR analysis, NMR data processing, spectral assignment, metabolite identification NMR, peak assignment, NMR peak analysis, spectroscopy analysis, MestReNova, TopSpin, chemical shift assignment, Chenomx', 'NMR Analysis', 'D.NMR', NULL, 'A.NMR', 'Raw', 'Analyzed', NULL, NULL, NULL, NULL, NULL, 91);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Organ-on-a-Chip Device Fabrication', 'This assay fabricates microfluidic organ-on-a-chip devices and seeds them with cells so they reproduce tissue-level structure and flow. Device layers are molded and bonded, channels and gel regions are filled with cells in extracellular matrix, and the chip is perfused so cell-cell and cell-matrix organization can develop. It also covers microvascular network formation, in which endothelial cells self-organize into perfusable vessel networks inside the device, measured by network length, branch points and mesh area. The finished chip is used for imaging, permeability and cancer cell extravasation experiments.', 'OOC fabrication, organ chip creation, microfluidic organ chip, tissue chip fabrication, body-on-chip, organ-on-chip assembly, microfluidic chip fabrication, organ-on-chip creation, PDMS molding, lab-on-chip, OOC assembly, chip manufacture, microfluidic device fabrication, chip fabrication, PDMS chip, lab-on-chip creation, OOC device, organ-on-chip, microvascular network, vascular chip assay, angiogenesis chip, microvascular formation, endothelial network, vascular OOC, vasculogenesis, microvasculature, HUVEC, perfusable vasculature, tube formation assay', 'Microfluidic Device Creation, Microvascular Network Formation, Device Creation, Microvascular Network Formation Assay', 'CEL', 'TIS', 'OOC or CEL', 'Source', 'Processed', NULL, NULL, NULL, NULL, NULL, 84);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Pathogen Challenge and Antibody Depletion', 'This assay challenges animals with a pathogen such as Mycobacterium tuberculosis, and can pair the challenge with antibody treatment that depletes a specific immune cell population. Mice and non-human primates are given a defined agent, amount, route and schedule, with any depletion on its own timeline, and are then followed and sampled; mouse challenge experiments also record the strain, sex and age of the animals. The challenged animal is the source of the downstream samples, so outcomes can be tied to vaccine efficacy and immune correlates of protection.', 'pathogen challenge antibody depletion, infection and antibody removal, challenge and passive transfer, depletion infection model, antibody challenge, antibody depletion, antibody administration, passive immunization, antibody infusion, antibody exposure, bacterial infection, pathogen challenge, bacterial inoculation, infection model, microbial challenge, in vivo infection, Mtb challenge, mouse challenge experiment, murine infection, in vivo mouse challenge, experimental mouse model, mouse treatment protocol, murine challenge, mouse infection model, mouse treatment experiment, in vivo mouse model, mouse exposure, in vivo, mouse study, vaccine challenge study, murine model', 'Antibody Challenge, Antibody Treatment, Bacterial Challenge, Pathogen Challenge, Antibody Depletion, Mouse Challenge Experiment, Mouse Challenge', 'BAC or AB or VIR', NULL, 'MUS or PAV', 'Source', 'Source', NULL, NULL, NULL, NULL, NULL, 133);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Patient Visit', 'This assay captures administrative and clinical metadata associated with patient study visits, serving as a structured data collection framework rather than a biological measurement assay. It records visit-level contextual information such as visit dates, timepoints, subject identifiers, clinical site details, and protocol-relevant annotations that are essential for linking experimental samples and assay results to their proper clinical context. This metadata layer ensures traceability and data integrity across all associated biospecimen collections and downstream analytical assays within the study.', 'clinical visit, study visit, patient encounter, blood draw visit, sample collection visit, longitudinal visit, study timepoint, clinical study, participant visit, subject visit, clinical metadata, follow-up visit, enrollment visit', NULL, 'PAT or NHP or PAV', NULL, 'PAV or TIS or PAT', 'Source', 'Processed', NULL, NULL, NULL, NULL, NULL, 56);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Patient-Derived Xenograft (PDX) Cell Line Generation', 'Patient-derived xenograft (PDX) cell lines are established by engrafting primary human tumor tissue or cells into immunocompromised mice, enabling the propagation and maintenance of tumor heterogeneity in an in vivo context. This process involves the surgical implantation or injection of patient tumor specimens into suitable murine hosts, followed by serial passaging to generate stable PDX models that recapitulate the molecular and phenotypic characteristics of the original tumor. The resulting PDX cell lines serve as biologically relevant preclinical tools for downstream applications including drug efficacy testing, biomarker discovery, and translational cancer research in mouse model systems.', 'PDX model, patient xenograft cell line, tumor cell line generation, patient-derived tumor, xenograft cell culture, PDX cell line, patient-derived xenograft culture, tumor model cell line, xenograft in vitro model, cell culture, PDX, xenograft, patient-derived xenograft, PDX-derived cell line, tumor engraftment', 'PDX Cell Line Generation', 'CEL or TIS', NULL, 'MUS or CEL', 'Source', 'Source', NULL, NULL, NULL, NULL, NULL, 172);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Permeability Analysis', 'This assay evaluates the permeability characteristics of biological membranes, barriers, or compound formulations, measuring the rate and extent of molecular transport across a defined membrane system. The analysis is conducted using standardized permeability protocols. Results typically quantify flux, permeability coefficients, or transport rates to assess barrier integrity or compound penetration potential.', 'barrier permeability analysis, membrane transport analysis, TEER measurement, permeability coefficient, paracellular flux, transwell permeability, organ-on-chip analysis, vascular permeability, dextran permeability, FITC-dextran, endothelial barrier function, permeability assay', NULL, 'D.IMG', NULL, 'A.PERM', 'Raw', 'Analyzed', NULL, NULL, NULL, NULL, NULL, 82);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('PET/CT Scan', 'A PET/CT scan combines positron emission tomography with computed tomography to visualize metabolic activity and anatomical structure. It provides functional imaging for research or diagnostic applications.\nInput: Live subject or biological model\nOutput: PET/CT imaging data showing metabolic and anatomical information.', 'PET-CT, positron emission tomography, CT scan, nuclear imaging, FDG-PET, metabolic imaging, hybrid imaging, medical imaging, PET imaging, computed tomography, 18F-FDG, radiotracer, microPET', 'PET-CT Scan', 'PAV', NULL, 'D.IMG', 'Source', 'Raw', NULL, NULL, NULL, NULL, NULL, 112);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('PET/CT Scan Analysis', 'This step quantifies reconstructed PET and CT image series. Lesions and reference tissues are segmented on the fused images, and tracer uptake is expressed as standardized uptake values along with volumetric measures such as lesion volume and total lesion glycolysis. Outputs are per-lesion and per-subject measurement tables used to assess disease burden and treatment response.', 'PET-CT analysis, nuclear imaging analysis, FDG uptake analysis, volumetric PET analysis, SUV analysis, metabolic imaging analysis, medical image analysis, standardized uptake value, SUVmax, PET quantification, lesion segmentation, granuloma analysis', NULL, 'D.IMG', NULL, 'A.CTSC', 'Raw', 'Analyzed', NULL, NULL, NULL, NULL, NULL, 175);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Polymerase Chain Reaction (PCR)', 'PCR amplifies a defined DNA or RNA target through repeated cycles of denaturation, primer annealing and enzymatic extension. Purified nucleic acid is combined with sequence-specific primers and polymerase in a thermocycler; RNA targets are first reverse transcribed, and real-time formats follow amplification with a fluorescent reporter such as a TaqMan probe or SYBR Green so starting amounts can be quantified from cycle threshold values. The assay covers conventional, quantitative and digital formats, read out by gel electrophoresis, fluorescence or sequencing depending on the format.', 'PCR, qPCR, RT-PCR, gene amplification, primer-based amplification, DNA amplification, quantitative PCR, endpoint PCR, conventional PCR, genotyping PCR, PCR amplification, thermocycler, reverse transcription PCR, qRT-PCR, quantitative RT-PCR, real-time PCR, gene expression qPCR, mRNA quantification, TaqMan assay, SYBR Green PCR, RT-qPCR, reverse transcription quantitative PCR, Ct value, delta delta Ct, QuantStudio', 'PCR: Validation Data, Real-time RT-PCR', 'RNA or DNA', NULL, 'D.PCR', 'Processed', 'Raw', NULL, NULL, NULL, NULL, NULL, 137);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Protein Extraction', 'Protein extraction from tissue samples is a preparative procedure designed to isolate and solubilize the total protein content from biological tissues for downstream quantitative or qualitative analyses. The process typically involves mechanical disruption (e.g., homogenization) and/or chemical lysis of tissue using detergent-based buffers (such as RIPA or similar lysis buffers), followed by centrifugation to remove cellular debris and insoluble material. The resulting protein-containing supernatant can subsequently be used in applications such as Western blotting, ELISA, mass spectrometry, or protein quantification assays to characterize protein expression, abundance, or activity within the tissue of interest.', 'protein isolation, protein purification, cell protein extraction, tissue protein extraction, total protein extraction, sample preparation, protein lysate, RIPA extraction, protein solubilization, BCA assay, protein precipitation', NULL, 'TIS or CEL', NULL, 'CEX', 'Processed', 'Processed', NULL, NULL, NULL, NULL, NULL, 125);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Proximity Extension Assay (PEA)', 'The Proximity Extension Assay (PEA) is a high-multiplex immunoassay technology used to quantify protein biomarkers in biological samples, typically plasma or serum, by exploiting dual-antibody recognition coupled with DNA reporter extension. In this method, pairs of oligonucleotide-labeled antibodies bind simultaneously to their target protein, which brings their oligonucleotide tags close enough to hybridize and be extended into a DNA reporter. The reporter is then amplified and quantified by real-time PCR or sequencing, giving a relative level for each target protein.', 'Olink PEA, proximity extension assay, protein biomarker quantification, Cq value, high-sensitivity protein panel, Olink assay, proximity extension, proximity ligation, protein biomarker panel, PEA, high-sensitivity proteomics panel, immunoassay, Olink Target 96, Olink Explore, NPX', 'Proximity Extension Assay', 'TIS', NULL, 'D.PEX', 'Processed', 'Raw', NULL, NULL, NULL, NULL, NULL, 171);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('RaDR Fluorescence Microscopy Image Machine Learning Analysis', 'This step scores recombination events in RaDR reporter tissue from fluorescence microscopy images. Machine learning models are applied to the image stacks to detect, classify and count fluorescent recombination foci and to reject imaging artifacts, in place of manual scoring of each field. Outputs are per-image and per-animal foci counts and frequencies, with the classifications kept so scoring can be audited.', 'RaDR analysis, machine learning imaging, fluorescence ML analysis, automated image classification, RaDR microscopy, deep learning image analysis, RaDR image ML, machine learning image analysis, automated fluorescence analysis, deep learning microscopy analysis, image analysis, RaDR-GFP, Rosa26 direct repeat, homologous recombination reporter, recombination foci counting', 'RaDR Image Machine Learning Analysis', 'D.IMG', NULL, 'A.IMG', 'Raw', 'Analyzed', NULL, NULL, NULL, NULL, NULL, 103);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('RNA Extraction', 'RNA extraction is a laboratory procedure used to isolate and purify total RNA from biological samples, serving as a foundational step for downstream transcriptomic analyses such as RNA sequencing, RT-PCR, or microarray profiling. The process typically involves cell lysis, denaturation of protein-RNA complexes, and purification using methods such as phenol-chloroform extraction, silica column-based kits, or magnetic bead-based approaches to yield high-quality RNA free of DNA, protein, and other contaminants. Key quality metrics assessed during and after extraction include RNA integrity number (RIN), A260/A280 and A260/A230 absorbance ratios, and RNA concentration, which are commonly measured using instruments such as a NanoDrop spectrophotometer or Bioanalyzer. Proper sample handling, including maintenance of an RNase-free environment and cold-chain integrity, is critical to preserving RNA quality and ensuring reproducibility across experimental conditions.', 'RNA isolation, RNA purification, total RNA extraction, Trizol extraction, column RNA extraction, RNA integrity RIN, RNA isolation kit, sample preparation, RNeasy, mRNA isolation, DNase treatment, RNA cleanup, phenol-chloroform RNA extraction', 'RNA Isolation', 'TIS or CEX or CEL or OOC', NULL, 'RNA', 'Processed', 'Processed', NULL, NULL, 'RNA::RIN, RNA::Protocol, RNA::Parent', NULL, NULL, 61);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Sample Processing', 'Sample processing prepares biological or environmental materials for downstream assays. It includes aliquoting, labeling, and quality control to ensure data integrity.\nInput: Collected sample\nOutput: Processed aliquot or prepared material for subsequent analysis.', 'sample preparation, biological sample processing, pre-analytical processing, sample handling, sample prep protocol, aliquoting, blood processing, plasma separation, serum separation, PBMC processing, biospecimen processing', NULL, NULL, NULL, NULL, 'Source', 'Processed', NULL, NULL, NULL, NULL, NULL, 116);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Scanning Electron Microscopy', 'Scanning electron microscopy (SEM) images the surface of a material at high magnification with a focused electron beam, used here to inspect filter devices and chemical materials.\nInput: Filter device (FLT) or chemical sample (CHM)\nOutput: Electron micrographs (D.IMG).', 'scanning electron microscopy, SEM, electron microscopy, surface imaging, micrograph, materials characterization, microscopy, SEM imaging, FE-SEM, EDS, energy-dispersive X-ray spectroscopy', NULL, 'FLT or CHM', NULL, 'D.IMG', 'Source', 'Raw', NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Sensor Creation', 'Sensor creation involves designing and assembling devices that detect physical, chemical, or biological signals. It combines materials engineering and functionalization to produce a responsive detection unit.\nInput: Design materials and sensor components\nOutput: Fabricated sensor prototype ready for calibration or testing.', 'biosensor fabrication, sensor development, electrochemical sensor construction, device fabrication, sensor manufacturing, biosensor, electrode functionalization, surface functionalization, sensor prototype, sensor design', 'Sensor Fabrication', NULL, NULL, 'SNSR', 'Source', 'Processed', NULL, NULL, NULL, NULL, NULL, 126);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Short Read Sequencing', 'Short read sequencing reads prepared libraries on high-throughput instruments to produce large numbers of short sequence reads. Libraries are loaded onto Illumina sequencing by synthesis platforms such as MiSeq, NextSeq, HiSeq and NovaSeq, or comparable short read instruments, and sequenced single or paired end at read lengths of roughly 50-300 bases. It yields raw read files with per-base quality scores, which alignment, expression and variant calling steps then consume.', 'Illumina sequencing, short-read NGS, paired-end sequencing, next-generation sequencing, 150bp reads, sequencing run, HiSeq NovaSeq, sequencing, NGS, short-read sequencing, high-throughput sequencing, RNA-seq, bulk RNA-seq, Element AVITI, NovaSeq, HiSeq, Illumina, MiSeq, NextSeq, sequencing by synthesis', 'Illumina Sequencing, Illumina Next-Generation Sequencing', 'DNA', NULL, 'D.SEQ', 'Processed', 'Raw', NULL, 'GEO, SRA', NULL, NULL, NULL, 64);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Single Cell Clustering Analysis', 'Single cell clustering analysis organizes single-cell expression data into groups with shared transcriptional profiles. It applies dimensional reduction and clustering algorithms to identify cellular subpopulations.\nInput: Single-cell expression matrix\nOutput: Clustered dataset and annotated cell-type identities.', 'scRNA clustering, Seurat clustering, Leiden clustering, cell type annotation, UMAP clustering, dimensionality reduction clustering, sequencing analysis, Scanpy clustering, Louvain clustering, cell type identification, marker gene detection, subclustering', 'Single Cell Clustering', 'A.SCXP', NULL, 'A.SCCL', 'Analyzed', 'Analyzed', NULL, NULL, NULL, NULL, NULL, 107);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Single Cell Expression Analysis', 'This assay quantifies gene expression at single-cell resolution by linking individual cell transcriptomic profiles to associated experimental or clinical data, enabling integrative analysis across multiple data modalities. Single-cell RNA sequencing (scRNA-seq) technology is employed to capture and measure the transcriptional activity of individual cells, generating high-dimensional expression matrices that are subsequently processed through quality control, normalization, and dimensionality reduction pipelines. Downstream analyses include cell type classification, differential expression and trajectory inference, to study cellular heterogeneity and gene regulation.', 'scRNA-seq analysis, single cell gene expression analysis, droplet sequencing analysis, 10x Genomics analysis, single cell transcriptomics, single cell expression matrix, gene expression count matrix, feature-barcode matrix, scRNA expression data, single cell count table, sequencing analysis, Cell Ranger, Seurat, Scanpy, scRNA-seq quality control', 'Single Cell Expression Matrix Analysis', 'D.SEQ or DNA or A.ALN', NULL, 'A.SCXP', 'Raw', 'Analyzed', NULL, 'GEO', NULL, NULL, NULL, 111);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Single Cell Sequencing', 'Single cell sequencing generates sequencing data from individual cells within a mixed population. The assay involves capturing or barcoding single cells, amplifying nucleic acids, and sequencing the resulting libraries.\nInput: Single-cell DNA/RNA sample\nOutput: Sequencing file (e.g., FASTQ / D.SEQ) containing cell-resolved read data.', 'scRNA-seq, 10x Genomics, single cell sequencing, droplet-based sequencing, cell barcoding, scATAC-seq, single cell NGS, sequencing, single-cell RNA sequencing, scRNAseq, 10x Chromium, Seq-Well, Drop-seq, Smart-seq2', NULL, 'DNA', NULL, 'D.SEQ', 'Processed', 'Raw', NULL, 'GEO, SRA', 'D.SEQ::LibraryStrategy, D.SEQ::LibrarySource, D.SEQ::LibrarySelection', NULL, NULL, 108);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Single-Nucleus RNA Sequencing (snRNA-seq)', 'Single-nucleus RNA sequencing (snRNA-seq) is employed to quantify genome-wide transcriptional activity at single-cell resolution by isolating and sequencing RNA from individual nuclei derived from tissue samples. This approach generates an expression matrix capturing transcript counts per nucleus, enabling characterization of cell-type composition, gene expression profiles, and transcriptional heterogeneity within complex tissues. Downstream computational analysis of the resulting expression matrix typically includes quality filtering, normalization, dimensionality reduction, and clustering to identify distinct cell populations and differentially expressed genes across experimental conditions.', 'snRNA-seq, single nucleus sequencing, nuclear RNA, frozen tissue sequencing, nucleus isolation, single nucleus transcriptomics, sequencing, single-nucleus RNA-seq, snRNAseq, single nuclei sequencing, sNuc-seq, frozen tissue single cell', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 110);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Solid Phase Extraction (SPE)', 'Solid-phase extraction (SPE) is a sample preparation technique used to isolate, purify, and concentrate target analytes or remove unwanted matrix components from complex liquid samples prior to downstream chromatographic analysis (LC-MS or GC-MS). The method operates by passing a sample through a sorbent bed, formatted as cartridges, disks, or multi-well plates, where selective retention is achieved through controlled interactions between the analytes and the sorbent material, followed by sequential wash and elution steps to recover purified compounds. SPE is widely applied across environmental monitoring (water and soil contaminants), pharmaceutical and bioanalytical workflows (drugs and metabolites from plasma or urine), clinical and forensic toxicology, and food-safety testing (mycotoxins, pesticide residues, and veterinary drug residues), with microextraction variants available for reduced solvent consumption and higher-throughput formats.', 'solid phase extraction, SPE cleanup, sample cleanup, cartridge extraction, analyte enrichment, sample purification SPE, sample preparation, SPE, Oasis HLB, C18 cartridge, analyte preconcentration, water sample extraction', 'Solid Phase Extraction', 'WTR', NULL, 'CHM', 'Source', 'Source', NULL, NULL, NULL, NULL, NULL, 162);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Spatial Metabolomics', 'Spatial metabolomics is an analytical approach that maps the distribution and relative abundance of small molecules, lipids, and other metabolites directly within tissue sections or biological samples, preserving spatial context that is lost in conventional bulk metabolomics. This technique typically employs mass spectrometry-based imaging methods such as MALDI-MSI (Matrix-Assisted Laser Desorption/Ionization Mass Spectrometry Imaging), DESI-MSI (Desorption Electrospray Ionization), or related platforms, applied to cryosectioned or fresh-frozen tissue mounted on conductive slides. Sample preparation generally involves careful sectioning, matrix application (for MALDI-based workflows), and instrument acquisition across a defined spatial grid, followed by data processing to generate ion intensity maps correlated with tissue morphology. Downstream analysis integrates mass spectral identification of metabolite features with histological annotation, enabling spatially resolved profiling of metabolic states across distinct tissue regions, cell types, or microenvironments.', 'spatial metabolomics, MALDI metabolite imaging, MSI metabolomics, molecular metabolite mapping, tissue metabolite distribution, mass spectrometry, DESI-MSI, DESI imaging, metabolite imaging, spatially resolved metabolomics, tissue metabolomics', NULL, 'TIS', NULL, 'D.MSP', 'Processed', 'Raw', NULL, NULL, NULL, NULL, NULL, 94);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Spatial Proteomics', 'Spatial proteomics measures many proteins at once while keeping their position in the tissue. Sections are stained with panels of labeled antibodies and imaged cycle by cycle on multiplexed imaging platforms such as CODEX or PhenoCycler, GeoMx or imaging mass cytometry, so each target is recorded as its own image channel. It yields multichannel tissue images in which protein abundance, cell composition and co-localization can be mapped across the section.', 'spatial proteomics, tissue protein mapping, multiplexed protein imaging, DSP, IMC proteomics, GeoMx, CyCIF proteomics, imaging, CODEX, PhenoCycler, MIBI, imaging mass cytometry, Hyperion, GeoMx DSP', NULL, 'TIS', NULL, 'D.IMG', 'Processed', 'Raw', NULL, NULL, NULL, NULL, NULL, 69);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Spatial Transcriptomics', 'Spatial transcriptomics is a molecular profiling method that measures gene expression across tissue sections while preserving the spatial context of transcriptional activity within the tissue architecture. This assay captures genome-wide or targeted mRNA expression profiles by capturing polyadenylated transcripts at spatially barcoded locations, enabling the mapping of gene expression patterns to specific histological regions. Raw sequencing data are processed through dedicated bioinformatics pipelines to generate spatially resolved expression matrices, which are subsequently analyzed for cell type deconvolution, spatially variable gene identification, and ligand-receptor interaction mapping. The resulting data provide insights into tissue organization, cellular heterogeneity, and microenvironmental interactions within the context of intact tissue morphology.', 'Visium, spatial RNA-seq, spatial gene expression, 10x Visium, spatially resolved transcriptomics, in situ sequencing, spatial gene expression analysis, Visium analysis, spatially resolved analysis, in situ transcriptomics analysis, tissue transcriptomic mapping, spatial omics, Xenium, MERFISH, Slide-seq', 'Spatial Transcriptomics Analysis', 'TIS or D.IMG or D.SEQ', NULL, 'D.IMG or A.SPTX', 'Processed', 'Raw', NULL, 'GEO', NULL, NULL, NULL, 93);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Spectroscopy', 'Spectroscopy measures how a sample interacts with light to describe its composition, structure and concentration. Chemical and water samples are presented in cuvettes, plates or directly to the instrument and spectra are acquired across the relevant range, covering UV-visible absorbance and optical density, fluorescence excitation and emission, and vibrational methods such as infrared and Raman. It yields spectra from which concentrations follow by the Beer-Lambert relation or by comparison with reference standards, alongside photophysical parameters such as extinction coefficients and quantum yields.', 'spectroscopy, optical measurement, wavelength-based analysis, light interaction, spectrophotometry, molecular spectroscopy, Raman spectroscopy, spectrometer, atomic absorption spectroscopy, chemical spectroscopy, spectral measurement, UV-Vis spectroscopy, ultraviolet-visible spectroscopy, absorbance measurement, optical density, UV absorption, UV-Vis, UV/Vis, absorbance spectrum, UV-visible spectrophotometry, fluorescence spectroscopy, emission spectroscopy, absorption spectroscopy, optical spectroscopy, excitation emission measurement, fluorometry, fluorimetry, quantum yield, extinction coefficient, photoluminescence, excitation spectrum, emission spectrum', 'UV-Vis Spectroscopy, Absorption and Emission Spectroscopy', 'CHM or WTR', NULL, 'D.SPC or CHM', 'Source', 'Raw', NULL, NULL, NULL, NULL, NULL, 25);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Spectroscopy Analysis', 'Spectroscopy analysis processes acquired spectra into quantitative results. Spectra are baseline corrected, smoothed and calibrated, then peaks are fitted or deconvolved and intensities converted to concentrations or other derived quantities against standards or reference spectra. Outputs are peak tables, fitted parameters and concentration estimates for each measured sample.', 'spectral analysis, peak analysis, wavelength intensity analysis, absorption emission analysis, spectroscopy data processing, absorbance analysis, emission analysis, UV-Vis analysis, fluorescence data processing, peak fitting, baseline correction, spectroscopy analysis, Raman spectral analysis, spectral deconvolution, FTIR analysis', 'UV-Vis Spectroscopy Analysis, Absorption and Emission Spectroscopy Analysis', 'D.SPC', NULL, 'A.SPC', 'Raw', 'Analyzed', NULL, NULL, NULL, NULL, NULL, 71);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('SureQuant Analysis', 'SureQuant analysis processes targeted mass spectrometry data to quantify peptides or proteins using internal standards. It calculates absolute or relative abundance values from internal-standard-triggered targeted acquisitions, a parallel reaction monitoring (PRM) style method.\nInput: Raw SureQuant mass spectrometry data\nOutput: Processed quantitative protein measurements and validation metrics.', 'SureQuant, targeted proteomics, heavy-labeled standard peptide, IS-PRM, triggered data-dependent acquisition, internal standard quantification, Orbitrap targeted MS, proteomics, parallel reaction monitoring, PRM, targeted mass spectrometry, absolute protein quantification, Skyline', NULL, 'CEL and CHM', NULL, 'D.MSP', 'Source', 'Raw', NULL, 'PRIDE', NULL, NULL, NULL, 182);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Targeted Cancer Gene Panel Sequencing (Oncopanel)', 'Oncopanel is a targeted next-generation sequencing (NGS) assay designed to detect somatic mutations, copy number alterations, and structural variants across a defined panel of cancer-relevant genes from tumor-derived nucleic acid samples. The assay employs hybridization-based capture or amplicon-based enrichment strategies followed by massively parallel sequencing to enable comprehensive genomic profiling of clinically actionable oncogenic alterations. Bioinformatic pipelines are applied to aligned sequencing data to identify single nucleotide variants (SNVs), insertions/deletions (indels), gene fusions, and copy number changes, with results interpreted in the context of established cancer driver genes and therapeutic targets.', 'oncopanel sequencing, cancer targeted NGS, tumor mutation profiling, cancer gene panel, somatic variant detection, oncology sequencing, targeted oncology sequencing, cancer genomics, targeted NGS oncology, sequencing, targeted panel sequencing, hybrid capture sequencing, DFCI OncoPanel, clinical tumor sequencing', 'Oncopanel', 'PAT', NULL, 'D.ONC', 'Source', 'Raw', NULL, NULL, NULL, NULL, NULL, 170);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Tensiometry Assay', 'Tensiometry is a physicochemical assay used to measure the surface tension of liquid samples, enabling the detection and quantification of surface-active compounds (surfactants) based on their ability to reduce interfacial tension at liquid-air or liquid-liquid boundaries. The method typically employs instruments such as a du Noüy ring tensiometer or Wilhelmy plate apparatus, which record the force required to detach a probe from the liquid surface, providing a direct measure of surface tension in units of mN/m. In a chemical validation context, this assay is used to confirm the surface-active properties of test compounds, assess concentration-dependent behavior (e.g., critical micelle concentration determination), and validate the physicochemical integrity of formulations. Results are analyzed by comparing measured surface tension values against reference standards or established thresholds to confirm the presence and potency of surface-active chemical entities.', 'tensiometry assay, surface tension assay, interfacial tension measurement, droplet tensiometry, surface energy measurement, pendant drop tensiometry, surface tension measurement, interfacial tension, droplet shape analysis, tensiometry, surfactant characterization, materials characterization, critical micelle concentration, du Nouy ring, Wilhelmy plate', 'Pendant Drop Tensiometry', 'CHM', NULL, 'D.TNSY', 'Source', 'Raw', NULL, NULL, NULL, NULL, NULL, 146);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Tissue Collection', 'Tissue collection obtains tissue or fluid specimens from a study animal or participant, for example at necropsy or during a clinical visit, and records the tissue type, anatomical site, collection method and how the specimen was preserved. Each specimen becomes a tissue sample (TIS) used by downstream assays.', 'tissue harvest, biopsy collection, tissue sampling, specimen collection, organ harvest, tissue extraction, sample collection, biopsy, tissue procurement, biospecimen collection, fluid collection', 'Tissue Extraction', 'MUS or PAV or NHP', NULL, 'TIS or CEX or PAV', 'Source', 'Processed', NULL, NULL, 'TIS::Parent, TIS::Type', NULL, NULL, 74);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Tissue Imaging', 'Tissue imaging acquires images of tissue sections or whole specimens, for example by brightfield, fluorescence or multiplexed microscopy, after fixation, sectioning and staining or labeling. The images (D.IMG) are used for morphological, histological or spatial analysis.', 'tissue microscopy, tissue slide imaging, fluorescence tissue imaging, histological imaging, tissue staining imaging, whole tissue imaging, glass slide scanning, digital slide scan, whole slide imaging, WSI scan, histology slide imaging, microscopy, slide scanner, Aperio', 'Slide Imaging', 'TIS or SLD or AB', NULL, 'D.IMG or ABP', 'Processed', 'Raw', NULL, NULL, NULL, NULL, NULL, 127);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Tissue Lysis', 'Tissue lysis disrupts tissue so that intracellular proteins, nucleic acids and metabolites are released into a homogeneous lysate. Material is homogenized by bead beating, rotor-stator homogenization, cryogenic grinding or freeze-thaw cycling in a buffer chosen for the target analyte class, then clarified by centrifugation. The clarified lysate is the input for extraction, immunoassay and mass spectrometry workflows. Tissue mass and buffer volume are noted so that downstream measurements can be normalized to input amount.', 'tissue homogenization, tissue disruption, tissue lysis, bead beating, mechanical tissue lysis, tissue protein extraction, sample preparation, tissue lysate, TissueLyser, Precellys, rotor-stator homogenization, cryogenic grinding', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 124);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Tissue Sectioning', 'Tissue sectioning is a histological preparation method in which fixed or frozen biological tissue samples are physically cut into thin slices (typically ranging from 1 to 10 micrometers for paraffin-embedded or cryosectioned material) using a microtome or cryostat instrument. This process preserves the spatial architecture and cellular morphology of the tissue, enabling downstream analyses such as immunohistochemistry, immunofluorescence, in situ hybridization, or routine histological staining. Sections are mounted onto glass slides and may undergo additional processing steps such as deparaffinization, antigen retrieval, or permeabilization prior to labeling and imaging-based readout.', 'cryosectioning, microtome sectioning, FFPE sectioning, tissue slicing, cryo-section preparation, histology sectioning, sample preparation, microtome, cryostat, paraffin sectioning, frozen sectioning, OCT embedding, slide preparation', NULL, 'TIS or CEL or SLD', NULL, 'SLD or D.IMG or D.MSI', 'Processed', 'Processed', NULL, NULL, NULL, NULL, NULL, 75);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Titer Assay', 'A titer assay measures how much antibody or other active agent a sample contains. Serum or other material is applied as a dilution series against antigen-coated beads, plates or target particles, and binding or activity is read at each dilution on a plate reader or cytometer. It yields the raw dilution series readings from which endpoint titer values are derived.', 'antibody titer assay, serology titer, bead-based titer, endpoint dilution, binding titer measurement, immunoglobulin titer, antibody titer, ELISA titer, binding titer, endpoint dilution titer, antibody quantification, immunoglobulin measurement, systems serology, viral titer, serum titer', 'Antibody Titer', 'TIS', NULL, 'D.TITR', 'Processed', 'Raw', NULL, NULL, NULL, NULL, NULL, 106);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('TransCompR Cross-Species Computational Modeling', 'This assay employs cross-species computational modeling to integrate and analyze transcriptomic or other molecular data across multiple organisms, enabling the translation of biological findings between species. The TransCompR framework applies statistical and machine learning methods to identify conserved gene expression patterns, pathways, or regulatory relationships by linking datasets derived from different species. Cross-species datasets are preprocessed, normalized and mapped through orthologs before model training and validation. Results provide mechanistic insights into conserved biological responses and support the extrapolation of preclinical animal model findings to human biology.', 'TransCompR modeling, cross-species computational model, species transcriptome translation, comparative model, trans-species modeling, TransCompR, cross-species modeling, comparative computational modeling, species translation model, cross-species computational, computational modeling, Translatable Components Regression, mouse-to-human translation, translational modeling, cross-species translation', 'TransCompR Cross Species Modeling', 'A.GEX', NULL, 'MDL', 'Analyzed', 'Analyzed', NULL, NULL, NULL, NULL, NULL, 168);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Variant Call Filtering', 'Variant call filtering takes aligned sequencing reads and produces a filtered set of variant calls, removing calls that fail quality, depth or strand-bias thresholds and annotating the ones that remain. The output is a variant call file ready for mutational or population analysis.\nInput: Aligned reads (A.ALN)\nOutput: Filtered, annotated variant calls (A.VCF).', 'variant calling, variant call filtering, VCF, variant filtering, SNV calling, indel calling, GATK, bcftools, variant annotation, somatic variants, germline variants, sequencing analysis, Mutect2, hard filtering, VQSR', 'Variant Calling Analysis, Variant Calling', 'A.ALN', NULL, 'A.VCF', 'Analyzed', 'Analyzed', NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Voltammetry', 'Voltammetry measures the current through a three-electrode cell while the applied potential is swept, using square-wave (SWV) or cyclic (CV) protocols, to characterize the redox behaviour of a chemical sample.\nInput: Chemical sample (CHM)\nOutput: Raw voltammograms (D.VLT).', 'voltammetry, cyclic voltammetry, CV, square-wave voltammetry, SWV, electrochemistry, redox, three-electrode cell, potentiostat, voltammogram, electrochemical characterization, square wave voltammetry', NULL, 'CHM', NULL, 'D.VLT', 'Source', 'Raw', NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Voltammetry Analysis', 'Voltammetry analysis turns raw voltammograms into blank-subtracted curves and redox descriptors such as peak potentials and currents, and can fit them with digital simulations (for example DigiElch).\nInput: Raw voltammograms (D.VLT)\nOutput: Voltammetric analysis results (A.VLT).', 'voltammetry analysis, voltammogram analysis, blank subtraction, redox potential, peak current, DigiElch, digital simulation, electrochemical simulation, electrochemical analysis, peak potential, cyclic voltammetry analysis, half-wave potential, square-wave voltammetry analysis', NULL, 'D.VLT', NULL, 'A.VLT', 'Raw', 'Analyzed', NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Water Quality Detection', 'Water quality detection measures chemical and physical properties of a collected water sample, such as pH, conductivity, disinfectant residuals or target contaminants, with field or laboratory instruments. Each run produces a water quality data record linked to the water sample it came from.\nInput: Water sample (WTR)\nOutput: Water quality data (D.WTR).', 'water quality, water quality testing, water testing, drinking water analysis, water chemistry, contaminant detection, pH, conductivity, chlorine residual, Superfund, SRP, disinfection byproducts, DBP, trihalomethanes, haloacetic acids', 'Water Quality Testing', 'WTR', NULL, 'D.WTR', 'Source', 'Raw', NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Western Blot', 'Western blot is a widely used immunodetection technique that separates proteins by molecular weight via gel electrophoresis, transfers them onto a membrane (typically nitrocellulose or PVDF), and detects specific target proteins using primary and secondary antibodies conjugated to reporter molecules such as horseradish peroxidase or fluorescent dyes. Sample preparation typically involves cell or tissue lysis, protein quantification, and denaturation in SDS-containing loading buffer prior to electrophoresis. Detection is commonly achieved through chemiluminescent or fluorescent imaging systems, with band intensity analyzed using densitometry software to enable semi-quantitative assessment of protein expression levels. This assay is routinely employed to characterize protein abundance, post-translational modifications, and molecular weight confirmation across a wide range of biological samples.', 'western blot, immunoblot, SDS-PAGE, protein gel, WB, blotting, nitrocellulose membrane, protein band detection, Western blotting, immunoblotting, PVDF membrane, chemiluminescent detection, LI-COR Odyssey', NULL, 'CEX or CEL or TIS', NULL, 'D.WBLT', 'Source', 'Raw', NULL, NULL, NULL, NULL, NULL, 76);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Western Blot Analysis', 'Western blot analysis quantifies protein signals from blot images produced at the bench. Band boundaries are defined and densitometry is used to measure intensities, which are corrected for background and normalized to a loading control such as beta-actin, GAPDH or tubulin. Results are reported as relative expression values per lane and condition, suitable for comparison across treatment groups.', 'western blot analysis, immunoblot analysis, SDS-PAGE analysis, densitometry, protein expression analysis, WB quantification, chemiluminescent blot analysis, band quantification, band intensity, loading control normalization, Image Studio', NULL, 'D.WBLT', NULL, 'A.WBLT', 'Raw', 'Analyzed', NULL, NULL, NULL, NULL, NULL, 184);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('X-ray Crystallography', 'Single-crystal X-ray crystallography is a structural determination technique that measures the diffraction pattern of X-rays passing through a crystalline sample to elucidate the three-dimensional atomic and molecular structure of a compound. In this assay, a suitable single crystal is mounted and exposed to an X-ray beam, and the resulting diffraction data are collected, indexed, and refined to yield precise bond lengths, bond angles, torsion angles, and absolute configuration. The method provides unambiguous structural characterization of small molecules or macromolecules. Crystallographic datasets (for example structure factors and CIF files) are usually deposited in a public database for validation.', 'X-ray crystallography, XRD, crystal structure determination, single crystal diffraction, Bragg diffraction, 3D molecular structure, small molecule crystallography, diffraction analysis, single crystal XRD, materials characterization, X-ray diffraction, SC-XRD, crystal structure, CIF file, structure refinement', 'Crystallography, Single-crystal X-ray Crystallography', 'CHM', NULL, 'D.CRY', 'Source', 'Raw', NULL, NULL, NULL, NULL, NULL, 142);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('X-ray Photoelectron Spectroscopy', 'X-ray Photoelectron Spectroscopy (XPS) is a surface-sensitive analytical technique that measures the elemental composition, chemical state, and electronic structure of materials by irradiating a sample surface with X-rays and detecting the kinetic energy and number of photoelectrons emitted from the top 1–10 nm of the material. This assay provides quantitative information on atomic concentrations and chemical bonding environments of elements present at or near the sample surface, enabling characterization of thin films, coatings, nanoparticles, and biomaterial interfaces. Data are typically acquired under ultra-high vacuum conditions using a monochromatic X-ray source, with spectral analysis performed by binding energy peak identification, curve fitting, and comparison to reference databases to determine elemental and chemical speciation.', 'XPS, X-ray photoelectron spectroscopy, surface analysis, elemental composition, binding energy measurement, ESCA, surface chemistry, spectroscopy, photoelectron spectroscopy, chemical state analysis, core-level spectra, depth profiling', NULL, 'CHM', NULL, 'D.XRS', 'Source', 'Raw', NULL, NULL, NULL, NULL, NULL, 157);
